// Server-only source; not a public static asset.
export const internalBundle = "const platformSettings = {};\nlet platformSettingsReady = false;\nlet platformSettingsQueue = Promise.resolve();\nasync function hydratePlatformSettings() {\n  const response = await fetch('/api/platform/settings',{cache:'no-store',credentials:'same-origin'});\n  if (!response.ok) throw new Error('Platform settings unavailable');\n  Object.assign(platformSettings,(await response.json()).settings);\n  platformSettingsReady = true;\n}\nfunction persistPlatformSettings() {\n  if (!platformSettingsReady) { toast('Platform settings not loaded; changes not saved.','error'); return; }\n  const snapshot = JSON.parse(JSON.stringify(platformSettings));\n  platformSettingsQueue = platformSettingsQueue.catch(()=>{}).then(async()=>{\n    for (const key of [\"roadmap\",\"changelog\",\"upvotedRoadmap\",\"crTab\",\"onepager\"]) {\n      if (!Object.hasOwn(snapshot,key)) continue;\n      const r=await fetch('/api/platform/settings',{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({key,value:snapshot[key]})});\n      if (!r.ok) throw new Error('Platform settings save failed');\n    }\n  }).catch(()=>toast('Platform settings not saved. Please retry.','error'));\n}\n\nfunction ensureQaView() {\n  if (document.getElementById('qa')) return;\n  const main = document.querySelector('main');\n  if (!main) return;\n  const section = document.createElement('section');\n  section.id = 'qa';\n  section.hidden = true;\n  section.textContent = 'Live workspace QA execution is disabled. Run the repository regression suite against isolated test fixtures.';\n  main.appendChild(section);\n}\n\n;\n\n/* ==========================================================================\n   SaaS Spend Track - Phase 11\n   Changelog + Roadmap view\n   Two tabs in one surface:\n     - Changelog: chronological log of what shipped, per phase\n     - Roadmap: themed list of what's next, with status (next / planned /\n       exploring) and an upvote counter for internal prioritisation\n   Both are editable in-tool so the product team keeps them current\n   as new work ships.\n   ========================================================================== */\n\nconst CHANGELOG = [\n  { date: '2026-11-15', phase: 'Phase 54', title: 'Mobile layout rescue + PWA (install as app on iOS, Android, desktop)', kind: 'feature', items: [\n    'Mobile fix (triggered by Vinay\\'s screenshot showing broken header): topbar on mobile had fixed 56px height but urgency chips wrapped vertically and spilled over the dashboard content. Also plan badge / breadcrumb / mobile nav all competing for the same strip.',\n    'Topbar now grows vertically on mobile (height: auto, flex-wrap). Urgency strip is now horizontally scrollable instead of wrapping - all chips fit in one scrollable row. Mobile nav tighter. Main content padding reduced to claim horizontal space. Stat tiles 2-up on tablet, 1-up on phone.',\n    'All Phase 43-52 modals are mobile-rescued: signup takeover 16px padding, Command Palette slides up from bottom for thumb reach, Bulk Import modal fills viewport, Settings + Reports + Diagnostics all stack full-width. Onboarding checklist and Help launcher repositioned so they don\\'t overlap the mobile nav.',\n    'PWA foundation: manifest.webmanifest + sw.js service worker + iOS Safari meta tags. App is now installable on iOS (Share → Add to Home Screen), Android (Chrome auto-prompts), and desktop Chrome/Edge (URL-bar install icon). Runs standalone, works offline after first load.',\n    'New \"Install this app\" card in Settings with platform-detected instructions. Different copy for iOS Safari vs iOS non-Safari vs Android vs desktop.',\n    'Service worker uses stale-while-revalidate for the app shell, bypasses cross-origin requests (fonts, FX API, Apps Script endpoint) so dynamic data stays fresh.',\n    'Public handle: window.PWA = { canInstall, prompt, platform, isStandalone }',\n    'Shipped alongside: trial-tracking/NATIVE-APP-STRATEGY.md explaining Option A (PWA, shipped now), Option B (Capacitor wrapper to App Store + Play Store), Option C (React Native rebuild, not recommended). Decision framework for when to escalate from PWA to native.',\n    'TODO added to VINAY-TODO.md: create proper PNG icon pack (192×192, 512×512, 512×512 maskable) - current icon.svg works but real PWAs want PNG for all platforms. Design brief included.',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 53', title: 'Bug fixes found in self-review: onboarding checklist state-key bug + demo-data pre-completion', kind: 'fix', items: [\n    'FIX: Phase 43 onboarding checklist \"Upload your first contract\" and \"Add a vendor\" items referenced state.contracts and state.vendors - neither of which exist in the app. The app stores contracts as subscription.contract and vendors as entries in state.subscriptions. The two items would NEVER auto-complete even after the user did both actions. Found during Phase 52 self-review. Replaced with correct state.subscriptions checks.',\n    'FIX: Even after the above fix, both items would show pre-completed on first load because the demo workspace ships with 28 sample subscriptions (and several of them have .contract set). Added baselineSubs and baselineContracts snapshot captured when onboarding state is first created - the done() checks now require GROWTH beyond that baseline instead of mere presence.',\n    'baselinedAt timestamp stored alongside so future-us can see when the baseline was captured, useful when debugging.',\n    'No API surface change; monkey-patches and public handles unchanged. Existing users with onboarding state already created are grandfathered - baseline will be absent and the check falls back to a count > 0 comparison (undefined > 0 is false, so it still won\\'t pre-complete, which is the safer failure mode).',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 52', title: 'Diagnostics view + hardening (Settings → Diagnostics card)', kind: 'feature', items: [\n    'New Diagnostics card in Settings view: at-a-glance health check for every Phase 43-50 module. 4 tiles (modules OK, patches OK, recent errors, state size KB) + verdict line + expandable per-module details with per-module reset buttons.',\n    'Global error catcher: window.error and unhandledrejection events logged to window._diagErrors (rolling buffer of last 50) with timestamp, source, message, 3-line stack. Surfaced in the Diagnostics card.',\n    'Per-module reset without full data loss: 5 reset buttons each target one module (onboarding, currency, payment state, cmdpal recent, per-sub currency) without touching subscriptions / contracts / employees.',\n    '\"Run test suite\" button in the Diagnostics card: runs the full in-browser test suite (138 tests after Phase 51) inline and shows pass/fail/skip count + a list of failures with error messages. Useful when something looks broken and you want to know whether the API surface is still intact.',\n    '\"Export diagnostic report\" button downloads a .json with current diagnostic, workspace counts, user-agent, URL - useful for me to debug remotely from a copy-paste.',\n    'Keyboard shortcut: Ctrl+Shift+D (or Cmd+Shift+D) jumps straight to Settings → Diagnostics from anywhere.',\n    'Public handle: window.Diag = { check, runTests, errors, clear, reset, open }',\n    'Rationale: 8 phases shipped in one sitting with 36h until UAT. Instead of adding more surface area that could break, strengthen what\\'s there so when the user returns they can SEE the state of every module at a glance, not have to debug blind.',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 51', title: 'Expanded test coverage for Phases 43-50 (+22 tests) + UAT checklist', kind: 'quality', items: [\n    'Deliberate pause on new features to strengthen the foundation before building more on top. 8 phases in one sitting with 0 end-to-end user verification is a lot of unverified ground.',\n    'Added 22 new in-browser tests covering Phases 43-50. All API-boundary / handle-exists / monkey-patch-detected tests - no state mutations, no modal opens, no renderAll invocations (those caused the Puppeteer evaluator to hang mid-run).',\n    'Test coverage now 138 PASS / 0 FAIL / 8 SKIP (up from 116 PASS). New groups: phase43.onboarding, phase44.bulk, phase46.reports, phase47.settings, phase48.payment, phase49.cmdpal, phase50.subccy, integration.phase43to50.',\n    'Specific checks: OnboardHelp / BulkImport / Reports / Settings / MarkPaid / CmdPal / SubCurrency handles exist with required methods. formatMoney and monthlyCost are detectably monkey-patched. parseCSV survives quoted commas + tab delimiters. autoMap recognises 10+ common header aliases.',\n    'Idempotency fix: wrapper around defineTests gates on a sentinel (_p51_tests_registered) so our tests do not multiply when the test-report UI calls defineTests repeatedly.',\n    'New file trial-tracking/UAT-PHASE-43-50.md - ~15 minute human walkthrough covering every surface of the 8 new phases. Click-by-click instructions, expected results, cleanup steps. For deeper behavioural verification that the browser-less test runner can\\'t do (modal animations, PDF generation, drip emails actually arriving).',\n    'Known skip: Phase 45 drip has no browser-side testable surface; verification is Apps Script side via testDripNow() per DRIP-SETUP.md.',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 50', title: 'Per-subscription source currency (closes the \"future phase\" gap from Phase 47)', kind: 'feature', items: [\n    'Every subscription now carries sub.currency (defaults to USD for backward compat with 48 phases of pre-existing data).',\n    'monthlyCost() is monkey-patched to normalise each sub through USD using the FX cache from Phase 47 before returning. Dashboards that sum costs now actually convert first instead of adding INR, EUR, USD as if they were the same unit.',\n    'Display still routes through Phase 47\\'s formatMoney patch so the user sees everything in their chosen display currency.',\n    'Bulk import gets a Currency column in the mapping step. Auto-selects if the headers include \"currency\", \"ccy\", or \"curr\". Per-row currency is applied at commit time via a short-lived Array.prototype.push wrap - new subs get currency set before they land in state.',\n    'Per-cell symbol detection: notes/name containing ₹ / Rs / rupees → INR, € → EUR, £ → GBP, A$ / AUD → AUD, S$ / SGD → SGD, ¥ / JPY → JPY, AED / د.إ → AED, C$ / CAD → CAD. Fallback if no currency column was mapped.',\n    'Per-subscription currency editor: Command Palette → \"Edit per-subscription currency…\" opens a filtered list with per-row dropdowns and a Save All button. Bulk-edit across the whole book in seconds.',\n    'Subscription rows surface a small amber ccy-tag when the source currency differs from the display currency - power users can see at a glance which vendors are priced natively vs converted.',\n    'Public handle: window.SubCurrency = { edit, get, set } for QA and programmatic use.',\n    'FX fallback: if rates aren\\'t cached yet (e.g. first load with non-USD display), subs fall back to USD treatment temporarily rather than showing NaN. Rates fetch in the background and refresh on next renderAll.',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 49', title: 'Command palette (⌘K / Ctrl+K) - one-keystroke launcher for every action', kind: 'feature', items: [\n    'Keyboard shortcut Cmd+K (Mac) / Ctrl+K (Windows / Linux) opens a fuzzy-matching command palette. Click the compact ⌘K chip in the header as an alternative.',\n    'Indexes everything that matters: all 18 views, bulk import, load sample contract, 3 report exports, onboarding tour / help / checklist, currency shortcuts (INR, USD, EUR, GBP), workspace export, trial extension, plans view.',\n    'Direct Ask Track query: type \"ask: how many renewals this quarter\" and hit Enter - the palette opens Ask Track with the query pre-populated and submitted.',\n    'Keyboard-first: ↑↓ to move, Enter to run, Esc to close. Mouse hover also updates the selection.',\n    'Fuzzy ranking: exact prefix > word prefix > substring > keyword match > character-interleaved. Scoped to each command\\'s title + keywords + group name. Returns top 12.',\n    'Recent actions pinned at the top when the input is empty (last 5 used). Then top navigation items as defaults.',\n    'Grouped output (Navigate / Actions / Reports / Help / Settings / Payment / Ask Track) with subtle group labels.',\n    'Public handle: window.CmdPal = { open, close } for keyboard bindings and testing.',\n    'Hidden on claudeusercontent.com and file:// - same gate as the signup modal and onboarding - so demos stay clean.',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 48', title: 'Payment-return detection: stop the drip + unlock paid state automatically on Razorpay return', kind: 'feature', items: [\n    'Closes the embarrassing case: user pays on day 11, returns to the tool, sees \"Trial: 2 days left\" and gets a day-12 \"trial ends Friday\" email anyway.',\n    'Detection triggers (checked on every page load): ?razorpay_payment_id= / ?payment_id= query params (Razorpay default), ?paid=1 / ?status=success URL params, #paid / #payment-success hash, OR a sessionStorage trail dropped when the user clicked a Pay button (fallback for when Razorpay strips query params on return - if the user left 30s-30min ago and came back, inferred as paid).',\n    'Any Pay button (links to rzp.io, elements with data-pay / data-pay-india / data-pay-global attributes) gets instrumented with a click handler that sets sst_pay_pending in sessionStorage - so inference works even if the return URL has no params.',\n    'Celebratory one-shot modal on first detection: green check animation, \"Payment received\" headline, what-changes list (trial countdown removed, paywalls hidden, data preserved), payment reference echoed if we have it, Undo link for the false-positive case.',\n    'URL is cleaned after detection so a refresh does not re-fire the modal.',\n    'payment_completed event posted to the Apps Script sheet with method / payment_id / inferred flag - the drip\\'s runDailyDrip reads this and excludes the user from further emails within 24 hours.',\n    'workspace.plan flips from \"trial\" to \"paid\", workspace.paidAt stamped with ISO timestamp.',\n    'Trial-gating UI auto-hidden once paid: trial banners, countdown badges, data-trial-only elements removed. Plan badges change from \"Trial\" to \"Paid plan · Active\" with green styling.',\n    'Manual override in Settings: new \"I\\'ve paid - unlock my workspace\" card lets users mark paid by hand for bank transfers / cross-browser payments / cases where auto-detect misses. Takes an optional payment reference.',\n    'Public handle: window.MarkPaid = { manual, isPaid, state, undo } for support and QA.',\n    'Known limitation: without a Razorpay webhook into the Apps Script endpoint, server-side state is 24h behind the browser. Future phase: wire a Razorpay webhook so payment_completed hits the sheet instantly on successful charge, even if the user never returns to the tool.',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 47', title: 'Settings view + multi-currency display (USD / INR / EUR / GBP / AUD / SGD / AED / JPY / CAD)', kind: 'feature', items: [\n    'New Settings sidebar tab (last position) consolidating workspace + currency + data + trial + danger-zone controls that were previously scattered or missing',\n    'Display currency setting with 9 currencies supported. All $ amounts in the tool convert automatically - no refactor of 120+ formatMoney call sites required. The global formatMoney() and formatMoneyShort() are monkey-patched to run every value through live FX before display.',\n    'FX rates fetched from frankfurter.app (free, no API key, business-daily rates from the European Central Bank). Cached in localStorage for 24h to avoid hammering the API. Background refresh on load if user already picked a non-USD currency.',\n    'Workspace editor: company name + owner email, with inline save button that updates state.settings.workspace.',\n    'Data export: download the entire state object as .json (contracts, vendors, invoices, usage, onboarding, FX cache - everything). Routes through the existing downloadFile bridge so it works on both artifact and hosted.',\n    'Data import: restore from a .json export. Confirms before overwriting, reloads the page on success.',\n    'Trial controls: extend by 14 days (for prospects who ask for more time), reset to day 1 (for distributor demos). Both are instant localStorage edits; no server call.',\n    'Danger zone: clear everything. Triple confirm (prompt requires typing DELETE), wipes localStorage, sessionStorage, IndexedDB, then reloads.',\n    'Toast notifications for every action so the user knows the save landed.',\n    'Public handle: window.Settings = { open, setCurrency, refreshFx } for programmatic use and QA.',\n    'Known trade-off: this phase treats all contract costs as USD. For tools priced in local currency originally (e.g. a Rupee-only vendor), the displayed conversion will be nonsense in a different display currency. Future phase can add per-subscription source currency; this one gets the common 95% case right (USD originals, non-USD display).',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 46', title: 'Export deliverables: Reports view with monthly spend PDF, renewal roster CSV, savings opportunities PDF', kind: 'feature', items: [\n    'New \"Reports\" tab in the sidebar (between Risk and Playbook) lists three one-click exports, each generated live from current state (never cached - always current).',\n    'Monthly Spend Summary PDF: one-page branded report with four headline tiles (monthly spend, annualised, active vendors, renewals in next 90 days), top 10 vendors table, category bar-breakdown, and a highlighted list of renewals due in 90 days. Red-tag on anything under 30 days.',\n    'Renewal Roster CSV: next 12 months of renewals with vendor, category, team, renewal date, days until, notice date (computed from contract.noticeDays), notice period, auto-renew flag, annual cost, owner email, URL. Opens cleanly in Excel / Sheets / Numbers.',\n    'Savings Opportunities PDF: ranked findings across four categories - Underused licences (seat utilization < 70%), Auto-renew traps (renewing within notice+15 days), Overlapping tools (multiple vendors in the same category), Orphan contracts (no owner). Each finding shows estimated annual saving; total shown in a hero tile at the top.',\n    'All PDFs use html2pdf.js (already loaded on-demand from Phase 3) with a shared branded chrome: SST logo header + workspace name + date, A4 portrait, 2x scale for crisp text, light theme for printability.',\n    'All downloads route through the existing downloadFile() bridge (Phase 15) so they work on both the Claude artifact and the hosted app.',\n    'Telemetry: every report generation posts an event_type=export_<report_id> row to the Apps Script sheet with per-report metrics (vendors counted, total $ savings, renewals exported) - gives you adoption data per report.',\n    'Help launcher gets a new \"Download a report\" entry so first-time users discover the Reports view from onboarding.',\n    'Public handle: window.Reports = { spendSummary, renewalRoster, savings, view } for QA and for other code to call.',\n    'Empty-state handling: Reports view explains what the user needs to do first (upload a contract or run bulk import) when state.subscriptions is empty. Each card is disabled with \"Needs data\" button when its specific prerequisites are not met.',\n    'Footer teases scheduled email delivery of these reports as a future phase.',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 45', title: 'Trial email nurture drip (5 emails over 14 days, Apps Script time-driven)', kind: 'feature', items: [\n    '5-email sequence replacing the \"one welcome then silence\" gap. Day 2: fastest way to see the tool (sent only to users who haven\\'t loaded a contract yet). Day 4: three findings worth looking for (sent only to users who\\'ve loaded data). Day 8: what the first 90 days look like (ROI framing). Day 12: trial ends Friday. Day 14: last day.',\n    'Zero new client-side code. Browser already posts onboarding + bulk-import events to the Apps Script endpoint; the drip derives per-user state (signed up when, loaded contract, bulk imported, used Ask Track, paid) from the events sheet and picks the right email per user per day.',\n    'Runs via a daily time-driven trigger (9-10am local time). One email per user per day, max.',\n    'Paid users automatically excluded once any payment_completed / paid_marked / manual_paid cell is seen in their event history.',\n    'Opt-out: any email address in a sheet named \"Opt Out\" is excluded. Users who reply \"stop\" get added manually.',\n    'Logs every send back to the events sheet as event_type=drip_<id>_sent so the same email never goes twice.',\n    'Honest copy - no made-up customer logos, no invented testimonials, no fake urgency. Each email offers a concrete next action (open the Risk tab, see pricing, hit reply).',\n    'Branded HTML with blue CTA button + plain-text fallback for mail clients that strip HTML.',\n    'Test from the Apps Script editor via testDripNow() (sends immediately) or previewTrialState() (logs the state table without sending).',\n    'Setup walkthrough in trial-tracking/DRIP-SETUP.md: 3-minute install, trigger config, opt-out, how to add new emails, how to change copy.',\n    'What\\'s NOT in this phase: A/B subject-line testing, open/click tracking (requires pixel hosting, often blocked by corp mail anyway), firmographic segmentation (signup only collects email+company), Razorpay webhooks to stop drip instantly on payment (future phase).',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 44', title: 'Bulk CSV import for subscriptions (3-step modal with auto-mapping and fuzzy dedup)', kind: 'feature', items: [\n    'New \"Bulk import\" button on the Subscriptions view header opens a 3-step modal: paste or upload → map columns → preview and commit',\n    'CSV parser handles quoted fields with commas inside them, auto-detects tab vs comma delimiter, strips BOM / CRLF cleanly',\n    'Auto-mapper recognises common header aliases per field: Vendor/Tool/Software/SaaS → name, Annual cost/ACV/Spend → cost, Cycle/Billing/Frequency → cycle, Owner/Manager/Contact → owner, Renewal/Expires/End date → renewal, and 60+ other aliases',\n    'Fields supported: Vendor name (required), Cost (strips $ ₹ € £ commas), Billing cycle (coerced to monthly/yearly/quarterly), Category, Team, Owner email, Renewal date (ISO or natural), Licences, Notes, URL',\n    'Date parser handles ISO, US, Indian (DD/MM/YYYY), and natural formats like \"14 May 2026\"',\n    'Fuzzy duplicate detection using Levenshtein against existing vendor names: exact matches are always skipped, near matches (\"Slack \" vs \"Slack\") can be configured to skip or import anyway',\n    'Preview shows first 50 rows tagged New / Possible dupe / Exact dupe (skip) / Missing name (skip), with per-row cost / cycle / renewal summary',\n    'Summary tiles count New / Possible duplicates / Exact dupes / Missing-name rows before you commit',\n    'Template CSV download: 10 columns, 3 realistic sample rows (Salesforce / Zoom / Figma) to show the expected format',\n    'Post-import: switches to Subscriptions view, toasts \"Imported N subscriptions · skipped M duplicates\", triggers renderAll so dashboards refresh',\n    'Onboarding integration: bulk_import_completed event posts to the same Apps Script sheet as signup for funnel tracking, and a successful import auto-ticks the \"add_vendor\" and \"upload_contract\" checklist items',\n    'Help launcher now lists \"Bulk import from CSV\" as the second item (after Replay tour) so first-time users discover it from the onboarding panel',\n    'Dark theme matching signup modal, Esc / backdrop click / X all close, responsive down to mobile',\n    'Public handle: window.BulkImport = { open, close, parseCSV, autoMap } for QA and programmatic use',\n  ]},\n  { date: '2026-11-15', phase: 'Phase 43', title: 'In-app onboarding: checklist, guided tour, beacons, smart tips, help launcher (Whatfix-style)', kind: 'feature', items: [\n    'Onboarding checklist widget bottom-right: 6 first wins (upload contract, add vendor, ask Track, see forecast, see renewals, see risk) with progress ring, auto-ticking as the user completes each, collapsible panel, dismiss with confirm',\n    'First-visit guided tour: 5-step spotlight walkthrough of sidebar + dashboard + contracts + Ask Track + trial badge, runs once 1.2s after load, respects Escape and skip',\n    'Spotlight overlay: SVG mask cutout with pulsing blue ring, tooltip auto-positioned to each step with viewport clamping, Back/Next/Done controls, step counter',\n    'Beacons: pulsing blue dots on the Ask Track mic, Forecast tab, and Risk tab - dismiss on click',\n    'Smart tips: hover-reveal ? icons attached to any element with a data-tip attribute (sprinkle as needed)',\n    'Help launcher: pill button bottom-right that opens a searchable panel with 7 replayable flows plus a mailto for support',\n    'Funnel telemetry: every flow start/complete/skip, checklist item completion, beacon click, and help open POSTs to the same Apps Script endpoint as signup - new event_type values tracked in the Sheet',\n    'All UI hidden on claudeusercontent.com and file:// so artifact previews and local demos stay clean',\n    'All UI hidden until signup capture completes so we never stack two modals',\n    'State persists per workspace under state.settings.onboarding - resetAll helper exposed as window.OnboardHelp.resetAll() for QA',\n    'Fix: index.src.html restored as the canonical source template (Phase 42 accidentally overwrote it with the bundled output, breaking the bundle pipeline)',\n    'bundle.py updated to read index.src.html and write both the artifact copy and saasspendtrack-tool/index.html, so one command produces the deployable Pages bundle',\n  ]},\n  { date: '2026-11-14', phase: 'Phase 38', title: 'Signup: work-email only (reject personal domains), live Apps Script URL wired', kind: 'feature', items: [\n    'Signup modal now rejects personal email domains with a clear inline message naming the domain: \"gmail.com looks like a personal email. Please use your work email so we can match your trial to your company for follow-up and GST invoicing.\"',\n    'Block list: gmail, googlemail, yahoo (all country TLDs), outlook, hotmail, live, msn, icloud, me, mac, aol, protonmail, rediffmail, mail.com, gmx, yandex, qq, 163, 126, foxmail, zoho, fastmail, tutanota',\n    'Also blocks disposable email domains: mailinator, guerrillamail, tempmail, 10minutemail, yopmail, trashmail, maildrop, dispostable, sharklasers, throwawaymail',\n    'Subdomain-aware: foo.gmail.com also blocked',\n    'Pre-emptive language added to the modal: \"Work email only\" in the heading, and \"gmail, yahoo etc not accepted\" in the description so users do not even try',\n    'Apps Script endpoint URL wired in: https://script.google.com/macros/s/AKfycbyaZnzM7Qq22uRyAcQ_PEQuXpZNRkdFhJuz2PZ2Csn_bt7LN2HXa6F-CbAmkh684kA/exec',\n    'Submissions should land in the tracking Sheet within 1-2 seconds now that the live URL is in place',\n  ]},\n  { date: '2026-11-14', phase: 'Phase 37', title: 'Fix: CSS variable mismatch made signup modal (and other new views) unreadable in dark mode', kind: 'fix', items: [\n    'The signup modal rendered with transparent background and inherited text color because the CSS I wrote referenced var(--surface) / var(--ink-dim) which don\\'t exist in the tool\\'s theme (the tool uses var(--panel) / var(--text-dim))',\n    'Same mismatch hit the Licence forecast view, One-pager controls, Demo presets cards, and Vendor contacts table',\n    '97 bad var references in styles.css fixed with a global replace: --surface → --panel, --surface-2 → --panel-2, --ink-dim → --text-dim',\n    'Same fix applied to inline <style> blocks in extensions14, 16, 18, 19',\n    'Root cause: I built the marketing site first (which uses --surface/--ink) then pasted similar CSS into tool extensions without checking the tool\\'s theme system',\n    'Lesson: tool theme vars are --panel / --panel-2 / --text / --text-dim / --border / --accent. Future extensions should use these, not the marketing-site names',\n  ]},\n  { date: '2026-11-14', phase: 'Phase 36', title: 'Signup UX: confirm the email, allow change later, identity chip in sidebar', kind: 'feature', items: [\n    'Welcome toast now displays the full email the user registered with (\"Welcome. Confirmation sent to name@company.com\") instead of just the first part, so they can confirm they typed it correctly',\n    'Sidebar footer badge replaced with an identity chip showing \"Signed in as name@company.com\" plus a Change button',\n    'Clicking Change opens a dismissable version of the signup modal with the current email prefilled',\n    'Updating the email writes a second row to the tracking Sheet with event_type=email_changed and the previous_email captured so you see the switch',\n    'Change-mode modal supports Esc, backdrop click, and X button to dismiss (initial capture stays non-dismissable so we always get the email)',\n    'Apps Script headers updated: event_type and previous_email columns added so initial signups and email-changes land cleanly in the Sheet',\n    'Welcome toast on \"I\\'ve already paid\" path also shows the email they claimed',\n    'Setup doc updated with event_type examples',\n  ]},\n  { date: '2026-11-14', phase: 'Phase 35', title: 'Trial signup capture → Google Sheet dashboard', kind: 'feature', items: [\n    'New first-visit modal captures work email + optional company before the app renders',\n    'Submission POSTs to a Google Apps Script endpoint that appends a row to your tracking Sheet',\n    'Columns captured: timestamp, email, company, country (via ipapi.co), locale, referrer, UTM params, workspace_id, user_agent',\n    'Captured workspace never shows the modal again. Marked as paid when user clicks \"I\\'ve already paid, skip this\"',\n    'Offline/misconfigured endpoint: signup queued in localStorage under pendingSignups, retried on next page load - no lost signups',\n    'UTM params from the URL (?utm_source=distributor-jp&utm_campaign=cohort-1) captured for attribution per distributor',\n    'Setup docs: trial-tracking/TRIAL-TRACKING-SETUP.md + signup-endpoint.gs (Apps Script)',\n    'Looker Studio dashboard recipe included for charts over the Sheet',\n    'Console helpers: AskTrackSignup.setEndpoint(url) to configure at runtime without redeploy, AskTrackSignup.reset() to re-trigger the modal in your own browser for testing',\n    'Hidden in the Claude artifact preview to keep demos clean',\n  ]},\n  { date: '2026-11-14', phase: 'Phase 34', title: 'Tool surfaces fully synced to USD-only (Plans view, README, UAT)', kind: 'fix', items: [\n    'Added a proper USD price block to the Plans view in the tool, matching the marketing site and trial banner: $3,499/year, GST sub-line for India, feature list, Pay & activate button',\n    'Plans view Pay button carries data-pay-geo attribute so it geo-routes to the right Razorpay URL',\n    'Added refreshPayGeoLinks() helper + DOMContentLoaded init so static Pay links in index.html get the right URL on first render (previously only JS-injected links did)',\n    'README.md pricing section updated to USD-only',\n    'UAT.md pricing scenarios updated to check for $3,499/year, not ₹3,00,000',\n    'QA still green: 116 pass / 0 fail / 8 skip',\n    'Historical changelog entries kept as-is (they record the pricing journey)',\n  ]},\n  { date: '2026-11-14', phase: 'Phase 33', title: 'USD-only display + geo-routed Razorpay (clean one-currency UX)', kind: 'feature', items: [\n    'Pricing display is now USD-only everywhere: $3,499/year headline on marketing site, tool trial banner, trial expiry gate, one-pager',\n    'Sub-line clarifier: \"Billed annually · Indian customers: 18% GST added at checkout · Includes 250 active contracts\"',\n    'Geo toggle UI removed from both the marketing pricing card and the expiry gate - one currency, no confusion',\n    'Geo detection stays but is now used only to route the Upgrade/Pay button to the right Razorpay page: Indian IP goes to the India page (collects INR + GST), non-Indian IP goes to the International page (USD, placeholder URL set to rzp.io/rzp/INTERNATIONAL-PLACEHOLDER until Razorpay International Payments activates)',\n    'Pay button href resolved on load; if the ipapi.co lookup updates the geo preference, mounted pay links refresh via data-pay-geo hook',\n    'One-pager region dropdown removed (not needed for single-currency display)',\n    'Action for you: activate Razorpay International Payments, create the $3,499 USD page, send me the new URL to replace INTERNATIONAL-PLACEHOLDER',\n    'Action for you: file LUT on gst.gov.in for FY 2026-27 to zero-rate exports',\n  ]},\n  { date: '2026-11-14', phase: 'Phase 32', title: 'Clean single-currency per geo view (no cross-reference clutter)', kind: 'fix', items: [\n    'Global view now shows only $3,499/year with \"Billed annually via Razorpay\" sub-line - no mention of INR',\n    'India view now shows only ₹3,00,000/year with \"+ 18% GST, invoiced separately\" sub-line - no mention of USD',\n    'Toggle at top of the pricing card (🌐 Global / 🇮🇳 India) is the only acknowledgement that the other currency exists',\n    'FAQ answers for Zluri-comparison and on-prem questions no longer mention both currencies',\n    'Pricing FAQ keeps the full single-sentence breakdown ($3,499/year, ₹3,00,000 + GST for India) since it is directly answering the price question',\n    'Tool side (trial banner, expiry gate, one-pager) also cleaned: each shows only the active currency',\n    'Removed the dead live-FX code path (no longer needed since no view mentions the other currency)',\n  ]},\n  { date: '2026-11-14', phase: 'Phase 31', title: 'Geo-switched pricing: $3,499 USD default globally, ₹3,00,000 for India', kind: 'feature', items: [\n    'Marketing site now defaults to $3,499 USD/year as the headline price (follows the Freshworks / Zoho / Postman pattern for Indian SaaS going global)',\n    'Indian visitors see ₹3,00,000/year as headline instead, with USD shown as secondary',\n    'Geo detected via 3 signals in order: user override saved in localStorage, browser Accept-Language (fast + offline), then ipapi.co confirmation on first visit',\n    'Manual 🌐 Global / 🇮🇳 India toggle on the pricing card so any visitor can switch',\n    'Preference persists in localStorage key \"sst-geo\" and is shared between the marketing site and the tool',\n    'Tool side mirrors: trial banner shows \"Upgrade $3,499/yr\" for global or \"Upgrade ₹3,00,000/yr\" for India',\n    'Trial expiry gate has the same inline toggle',\n    'One-pager PDF gets a new \"Prospect region\" dropdown in its controls - distributor picks India (INR primary) or Global (USD primary) per prospect',\n    'Razorpay still collects ₹3,00,000 in INR for everyone (international card buyers pay the INR equivalent at the card issuer rate)',\n    'schema.org Product price reverted to 3499 USD; meta description and OG tags lead with USD',\n    'FAQ answers show both currencies together',\n  ]},\n  { date: '2026-11-13', phase: 'Phase 30', title: 'Removed static dashboard mock + simplified pricing to match Razorpay', kind: 'fix', items: [\n    'Removed the old static dashboard mock section from the marketing site (lines 413-468 of index.html) - the new animated Live Preview section built in Phase 28 is now the only dashboard preview on the page',\n    '\"See the dashboard\" hero CTA now routes to https://app.saasspendtrack.com (was an in-page #demo anchor)',\n    'Simplified pricing display to match what Razorpay actually collects: ₹3,00,000/year flat, with \"GST extra for Indian customers, invoice provided\" as a footnote rather than adding \"+ GST\" to the headline or showing ₹3,54,000 as the total',\n    'Consistency: Razorpay collects ₹3,00,000, GST invoice issued separately via Zoho Books for Indian B2B buyers',\n    'schema.org, OG tags, FAQ, pricing card, comparison, and tool trial banners all updated to the simpler format',\n  ]},\n  { date: '2026-11-13', phase: 'Phase 29', title: 'INR-anchored pricing + vinayraghavendran16@gmail.com + phone + company name fix', kind: 'feature', items: [\n    'Pricing anchor shifted to ₹3,00,000 INR excluding 18% GST (total payable ₹3,54,000 for India)',\n    'USD equivalent now derived live from the INR anchor via frankfurter.app - approx $3,600 USD at today\\'s rate',\n    'Marketing site pricing card shows ₹ as primary currency, with USD and GST breakdown below',\n    'Contact email changed from vinay@saasspendtrack.com to vinayraghavendran16@gmail.com across every surface',\n    'Phone number +91 91684 81989 added to the footer, trial banner, and one-pager default distributor info',\n    'Company name corrected to \"Whizzlead Solutions OPC Private Limited\" (no parens) in footer and all legal copy',\n    'One-pager default distributor info pre-filled with Vinay as signatory (overrideable per prospect)',\n  ]},\n  { date: '2026-11-13', phase: 'Phase 28', title: 'Repositioning: global teams + live FX + animated preview + Razorpay', kind: 'feature', items: [\n    'Positioning updated from \"Indian and APAC mid-market\" to \"global teams\" across every surface. US and UK buyers get the same message as Indian prospects, with India-specific features (lakh/crore, INR invoicing, GST) kept as capabilities not positioning',\n    'Price updated from $3,199 to ₹3,00,000/year',\n    'INR conversion on the marketing site is now LIVE via frankfurter.app (free, ECB daily rate, no auth) with 18% GST included, Indian lakh-style formatting (₹3,44,000), and the exchange rate + date shown inline',\n    'Static fallback shown first so the price never blanks out; live rate replaces it within a second',\n    'New Live dashboard preview section on the marketing site: faux browser chrome with 5 rotating scenes from the actual tool - Dashboard KPIs ticking, Ask Track typing + answer, Renewal Center lanes, Licence Forecast chart drawing, Risk analytics bars',\n    'Upgrade CTA across the tool (trial banner + expiry gate) now points to a Razorpay payment page (live URL: rzp.io/rzp/NCGW9GyD)',\n    'Marketing site pricing CTAs now include \"Pay & activate\" button pointing to Razorpay alongside \"Try it live\" and \"Book a demo\"',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 27', title: 'Pricing updated to ₹3,00,000/year (India excluding GST)', kind: 'feature', items: [\n    'Annual price updated from $3,000 to ₹3,00,000 across every surface - marketing site, one-pager PDF, trial expiry gate, trial banner, README, UAT',\n    'For India: pricing shown as approximately ₹2,65,000 per year with explicit \"excluding 18% GST\" note so Indian prospects see the final-invoice number',\n    'Extra-contracts pricing unchanged at $100/year per additional 50 contracts above 250',\n    'schema.org Product price metadata updated to 3199 USD so Google and search engines see the right value',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 26', title: 'Full cycle: QA expansion, UAT scenarios, docs refresh', kind: 'feature', items: [\n    'QA harness expanded to 124 tests covering Phases 22-25 (one-pager, trial gate, demo presets, vendor contacts, voice settings, Ask Track intents, fuzzy vendor matching, download bridge)',\n    'Headless test runner (run_qa.js) using Puppeteer + Chromium - runs the full suite in ~5 seconds and reports pass/fail/skip',\n    'Current status: 116 pass / 0 fail / 8 skip (skips need a real backend)',\n    'Three real bugs caught by the expansion and fixed: (1) a literal end-script tag inside a template literal broke the HTML bundle; (2) voiceSettings() crashed on load before state was initialised; (3) monthlyCost shadow collision in extensions13 duplicated the function with wrong weekly constant (4.33 vs 4.345)',\n    'New UAT.md: 10 scenario sections, 70+ test steps for manual pre-release walk-through, covering fresh-install, distributor demo cycle, trial gate, one-pager, contact book, Ask Track (text + voice), download audit, mobile, dark mode, marketing site',\n    'README.md refreshed to reflect Phases 1-25 (architecture, feature list, hosting, extensions table, pricing, running locally, bundling)',\n    'Smoke-test shortcut documented: run_qa.js + 6 manual steps for a 2-minute go/no-go after any push',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 25', title: 'Vendor contact book', kind: 'feature', items: [\n    'New Vendor contacts view: AE/CSM name, email, phone, LinkedIn, last/next outreach, notes per vendor',\n    'Four KPIs: vendors with contact, missing contact, stale (>60d since touch), portfolio value',\n    'Stale rows (no touch in 60+ days) highlighted red; 30-60 days aging highlighted amber',\n    'Contact pane also injected inline into the contract review modal so editing is one click from every vendor row',\n    'Draft renewal email button: pre-fills a mailto with subject + personalised body using the vendor name, annual commit, seat utilisation, and renewal date',\n    'Clicking draft automatically records today as the last-outreach date',\n    'Contact book persists per-vendor on the subscription record, survives preset swaps',\n    'PDF export supported',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 24', title: 'Demo seed-data switcher (3 industry presets)', kind: 'feature', items: [\n    'New Demo presets view with three industry-tailored seed datasets plus the Acme Corp default',\n    'Indian SaaS startup: Series B, 80 people, Bengaluru. 25 vendors weighted to engineering and PLG tools, INR costs',\n    'Mid-market BFSI: 420 people, Mumbai. 26 vendors weighted to security, risk, compliance, legal - matches the on-prem pitch',\n    'Manufacturing: 250 people, Chennai. 25 vendors weighted to ERP, CAD/PLM, supply chain, MES, shop-floor',\n    'One-click Load replaces current subscriptions / employees / invoices and clears chat history for a clean slate',\n    'Workspace / trial status is preserved so the dev controls on the Plans view still work between loads',\n    'Current preset is marked with a badge so the distributor knows which flavour is live before the next demo',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 23', title: 'Trial expiry enforcement', kind: 'feature', items: [\n    'Full-screen expiry gate blocks the app when the 14-day trial ends - three actions: Upgrade (mailto), mark as paid, or view data read-only',\n    'Grace mode banner at the top when ≤3 days remain, orange warn style with inline Upgrade CTA',\n    'Read-only mode blurs spend figures with a lock icon so the data is preserved but hidden until upgrade',\n    'switchView intercepts navigation on expired trials and keeps the Plans view accessible for self-service upgrade',\n    'Owner-only dev controls on the Plans view: reset to fresh trial, force-expire for demos, mark as paid/revert',\n    'Fresh-trial button resets the clock cleanly so the distributor can re-demo with the next prospect',\n    'window.AskTrackTrial exposes state/reset/expire for console use',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 22', title: 'Distributor one-pager (branded A4 PDF)', kind: 'feature', items: [\n    'New Distributor one-pager view under Workspace',\n    'Branded A4 single-page leave-behind rendered inline for preview',\n    'Personalisation: prospect name, distributor name, email, phone - all baked into the PDF',\n    'Four bands: hero + value prop, three-pillar problem/solution, pricing + differentiator, CTA with QR code to saasspendtrack.com and distributor contact',\n    'Download PDF button routes through the universal download bridge',\n    'Print button opens a clean print-ready window',\n    'QR code auto-generated via qrserver.com; encodes a prospect-tagged URL for simple attribution',\n    'Settings persist in state so the same inputs come back next time',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 21', title: 'Speak replies ON by default', kind: 'feature', items: [\n    'TTS voice reply now defaults to ON and persists across sessions in state.settings.voice.speakOn',\n    'Modal (Cmd+K) answers also speak the headline, not just the drawer and full chat view',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 20', title: 'Intent fixes: fuzzy vendor match + reliable Esc close', kind: 'fix', items: [\n    'Fuzzy vendor matching with Levenshtein distance - voice near-misses like \"hotspot\" now resolve to HubSpot, \"sells force\" to Salesforce. Threshold: 2 chars for short names, 3 for longer',\n    'Reordered intent router so simple \"spend on X\" is checked before the multi-slot \"dept spending on vendor\" pattern - fixes \"total spend on hotspot\" grabbing \"total\" as department and \"year\" as vendor',\n    'The dept+vendor intent now requires an explicit team/dept/department keyword, so generic questions never match it',\n    'When a vendor still cannot be matched, the response now shows the 5 closest vendor names as clickable chips - recover from a near-miss in one tap',\n    'Esc key now closes the modal from anywhere inside it (previously only worked if the input had focus)',\n    'Closing the modal also cancels any in-flight speech and recording - no more voice playing after dismiss',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 19', title: 'Live on app.saasspendtrack.com + voice language picker', kind: 'feature', items: [\n    'Hosted on Cloudflare Pages (saasspendtrack project) with custom domain app.saasspendtrack.com',\n    'Auto-deploy on every push to main branch via GitHub integration',\n    'wrangler.toml + _headers + _redirects shipped: single-page-application fallback, mic Permissions-Policy allowed, 1h cache on JS/CSS, no-cache on HTML for instant deploy rollout',\n    'TTS reply language now defaults to English - no more Hindi default',\n    'Voice settings pane in the Ask Track view: reply voice language, reply voice picker, mic input language',\n    '12 languages supported for both TTS and STT: English (US/India/UK), Hindi, Tamil, Telugu, Bengali, Marathi, Gujarati, Kannada, Malayalam, Punjabi',\n    'Scorer never crosses language families - picking English will never fall back to a Hindi voice (fixes the previous Hindi default)',\n    'Test voice button speaks a sample sentence in the chosen language - useful for confirming the voice is installed on this device',\n    'Mic input language takes effect on next press',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 18', title: 'Less robotic voice: prefer Natural/Neural, chunk at sentences', kind: 'feature', items: [\n    'Voice picker now scores every installed voice - Natural/Neural voices (Microsoft Edge\\'s Natural voices, Google WaveNet) win decisively over system voices (Veena, Microsoft Desktop)',\n    'Scoring also weights Indian English accent, female gender, and down-weights obvious formant voices',\n    'Text is split at sentence boundaries and spoken as separate utterances with light prosody variation per chunk - kills the monotone flatness',\n    'Currency ($12,500 / ₹5 lakh) and percentages read as natural language, not digit-by-digit',\n    'Lakh/crore conversion for Indian currency amounts over ₹1,00,000',\n    'Debug helpers: window.AskTrackVoice.listVoices() shows every voice and its score; setVoiceByName(\"name\") to override',\n    'Open your browser console and run AskTrackVoice.listVoices() to see which voices are installed on this device',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 17', title: 'Voice: Indian female voice + clearer mic errors', kind: 'feature', items: [\n    'Ask Track replies now use an Indian English female voice when installed on the device (Veena on macOS/iOS, Microsoft Heera on Windows, system Indian voice on Chrome/Android)',\n    'Softer cadence: rate 0.92, pitch 0.95 for a more soothing read-aloud',\n    'Graceful fallback chain if no Indian voice is installed: en-IN female → any en-IN → en-GB female → platform default',\n    'Mic errors now explain the cause: inside the Claude artifact preview the parent iframe does not grant microphone permissions-policy, so voice input is blocked there - works natively on any hosted copy',\n    'Browser-blocked mic errors now tell you how to unblock in one line (click the lock icon in the address bar)',\n    'no-speech / no-mic / network errors each have their own clear message',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 16', title: 'Renamed to Ask Track + 6 new intents', kind: 'feature', items: [\n    'Feature renamed from \"Ask the Corpus\" to \"Ask Track\" across every surface - topbar bar, modal, chat view, sidebar nav, docs',\n    'Six new intents added to the router to catch list-style questions that previously fell through: list_vendors, list_owners, list_contracts, count_vendors, department_list, help',\n    'Now answers: \"give me all vendor names\", \"list all vendors\", \"who owns what\", \"how many vendors do we have\", \"what departments do we have\", \"help\"',\n    'Fallback response now shows clickable chips of known intents when it cannot route - much shorter path from a miss to a hit',\n    'Type \"help\" anywhere to see every intent the router supports',\n    'Trademark note: Ask Track was chosen as a brand-anchored combination of two common words - clear in Class 42 SaaS, no known mark collision',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 15', title: 'Global command palette for Ask Track', kind: 'feature', items: [\n    'Persistent search bar in the topbar on every view - click it or press ⌘K / Ctrl+K',\n    'Centered modal with keyboard-first interaction: ↑↓ to navigate suggestions, ↵ to ask, Esc to close',\n    'Suggestions include starter questions plus \"Spend on <vendor>\" for every subscription in state',\n    'Voice input button inside the modal, same engine as the full view',\n    'Dedicated #chat view retained for persistent history and voice-reply',\n    'Floating pill now mobile-only (topbar bar collapses below 720px, pill takes over)',\n    'All in-browser: query → answer round trip under 20ms, no network call',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 14', title: 'Universal download bridge (artifact-safe)', kind: 'fix', items: [\n    'Every download button now routes through one bridge: claude.use(\"downloads\") when inside the Claude artifact viewer, classic anchor+blob everywhere else',\n    'Fixes silent download failures inside the artifact preview (PDF exports, CSV exports, JSON exports, ICS calendar, all template downloads)',\n    'Downloads capability declared on the artifact so the viewer prompts for save confirmation',\n    'Works natively with zero prompts on any hosted copy (Cloudflare Pages, Vercel, self-host)',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 13', title: 'Licence Forecasting (capacity planning)', kind: 'feature', items: [\n    'New Licence Forecast view under Operations',\n    'Per-vendor quarterly demand projection: Q+1 to Q+4',\n    'Model: demand(q) = active × (1 + headcount_growth)^q × (1 + adoption_growth)^q × utilisation_buffer × confidence_buffer',\n    'Capacity plan controls: org growth %, target utilisation, horizon, confidence',\n    'Per-department overrides: either growth % per quarter or target headcount at horizon',\n    'Recommendation per vendor: Add seats / Hold / Reclaim - with annual $ impact',\n    'Portfolio seat-demand curve chart (today vs. Q+1 through horizon)',\n    'All forecast settings persist to state and export to PDF',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 12', title: 'AI Chat on the contract corpus (text + voice)', kind: 'feature', items: [\n    'New Ask Track view and a floating Ask pill on every screen',\n    'Natural-language Q&A over vendors, contracts, invoices, licences, departments, risk, renewals, clauses, approvals, employees',\n    '14 intent patterns including: \"How much is marketing spending on Salesforce this quarter?\", \"How many Figma licences do I need next quarter?\", \"Which contracts have the highest risk?\", \"Which tools are underused?\", \"Cost per user for Slack\"',\n    'Voice input via the Web Speech API (SpeechRecognition) with recording state',\n    'Voice reply via SpeechSynthesis (toggle per surface)',\n    'Grounded answers only: every number sourced from state, with a why-this-answer trace per reply, and clickable sources back to the contract review modal',\n    'Chat history persists per workspace; clear control included',\n    'No external AI call - runs entirely in the browser',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 11', title: 'Changelog & Roadmap view', kind: 'feature', items: [\n    'New in-product changelog documenting every release with the date, phase and user-facing change',\n    'Themed roadmap view with upvote counter so the product team can prioritise from one surface',\n    'Both are editable in-tool and persist to state',\n    'Surfaced in the sidebar under Workspace',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 10', title: 'Data Sources + 44 connectors', kind: 'feature', items: [\n    'New Data Sources view consolidates every automated data-pull mechanism',\n    'Phase 1: Okta, Microsoft Entra ID, Google Workspace, JumpCloud (SSO)',\n    'Phase 2: 24 direct vendor APIs - Salesforce, Slack, Zoom, GitHub, Datadog, HubSpot, Atlassian, Notion, Figma, 1Password, DocuSign, Dropbox, Gong, Apollo, Intercom, Zendesk, Anthropic, Vercel, Segment, LinkedIn Sales Nav, Adobe, Snowflake, AWS, Rippling',\n    'Phase 3: 8 finance / AP feeds - QuickBooks, NetSuite, Tally, Zoho Books, Xero, SAP, Ramp, RazorpayX',\n    'Phase 4: 5 unified-API aggregators - Finch, Merge.dev, BetterCloud, Josys, Nudge Security',\n    'Phase 5: Chrome extension for shadow-IT discovery',\n    'Per-vendor source map table with current source, confidence rating (high/medium/low), last-sync timestamp, and all available connectors per vendor',\n    'Four KPIs: vendor coverage, spend coverage, not instrumented, data confidence breakdown',\n    'Simulated OAuth handshake and data pull populate realistic utilisation data today; real OAuth handlers drop into the same slots when the server tier ships',\n  ]},\n  { date: '2026-11-12', phase: 'Audit', title: 'Dark-mode contrast + mobile overflow fixes', kind: 'fix', items: [\n    'Six classes using ink-background with hardcoded white text now flip correctly in dark mode (Renegotiate button, Acknowledge hover, Most Popular tag, toasts, Done button in dropdowns, Open Approvals button)',\n    'Analytics view fixed-width SVG charts now scale fluidly below 900px',\n    'Dashboard horizontal overflow (13px) resolved',\n    'Mobile nav strip contained to viewport (was pushing the page 346px wide on Analytics)',\n    'Esc key now closes invite, OAuth and accept-invite modals (was only backdrop click)',\n    'Full QA suite: 80 pass, 0 fail, 8 skipped (backend-only)',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 9', title: 'QA harness + 88 in-browser tests', kind: 'feature', items: [\n    'New QA tab with Run All Tests, Re-run failed only, Download PDF',\n    '80 executable tests across Static sanity, Unit, State machines, Validation, SaaS-specific and Integration',\n    '8 tests explicitly skipped with reason (real email delivery, server-side auth, N+1 queries, rate limiting, webhook idempotency, async retries, row-level isolation, CVE scans)',\n    'Results persist to state; per-test duration and failure message inline',\n    'Found and fixed two real bugs during build: playbook phrase-rule needed explicit op=contains; PAGE_TITLES was not on window for extension hooks',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 8', title: 'Workspace, users, invites, trials', kind: 'feature', items: [\n    'New Workspace view with owner controls, trial countdown, four KPIs',\n    'Six roles: Owner, Admin, Finance, Legal, IT, Viewer',\n    'Invite flow generates a token-encoded link, opens the user\\'s mail client with a pre-filled draft',\n    'Accept flow at ?invite=<token> with expiry check and idempotency',\n    'Owner-protection: owner cannot be deactivated, role-changed or removed',\n    'Trial banner across the app when ≤7 days remain, red when expired',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 7', title: 'Mobile owner inbox', kind: 'feature', items: [\n    'Dedicated mobile-first surface for vendor owners',\n    'Direct-link mode via ?owner=email - hides the app shell, lands straight in the inbox',\n    'Three thumb-sized actions per card: Acknowledge, Renegotiate, Cancel',\n    'KPIs for Escalated / Due now / Total; collapsible details per card',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 6', title: 'Scenario Planner', kind: 'feature', items: [\n    'Model Cancel / Downgrade / Renegotiate / Consolidate per vendor; live annual delta',\n    'Four KPIs: new annual run-rate, delta, vendor count after, portfolio risk after',\n    'Saved scenarios persist; load and compare',\n    'PDF export of the full scenario plan',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 5', title: 'Clause commenting + approval chains', kind: 'feature', items: [\n    'New Approvals view with policy editor and pending/approved/rejected lanes',\n    'Five seeded rules: ≥₹5L → Finance Manager; ≥₹25L → + CFO; ≥₹1Cr → + CEO; critical risk → Legal; missing DPA → Security',\n    'Per-role Approve/Reject on each contract; banner in contract review modal',\n    'Per-clause comment threads inside the contract review modal (Finance / Legal / Security / IT / Procurement / Owner)',\n  ]},\n  { date: '2026-11-12', phase: 'Phase 4', title: 'Renewal Command Center', kind: 'feature', items: [\n    'One Monday working surface for renewals in next 30/60/90/120/180 days',\n    'Cards grouped by lane: Overdue, Critical (≤14d), Decide soon (≤45d), Upcoming, Will renew, In renegotiation, Downgrading, Cancelling',\n    'Each card shows act-by, renewal, owner (with escalation chain), risk, playbook deviations, waste signals',\n    'Four actions per card: Renew / Renegotiate / Downgrade / Cancel - decisions persist',\n  ]},\n  { date: '2026-11-11', phase: 'Phase 3.2', title: 'Dept-weighted risk + Legal review PDF', kind: 'feature', items: [\n    'New Risk-weighted spend by department panel in Analytics',\n    'Dedicated Legal Review PDF export from Playbook with executive summary, portfolio breakdown, per-vendor deviation cards, compliant-vendors appendix',\n  ]},\n  { date: '2026-11-11', phase: 'Phase 3.1', title: 'Custom dropdowns + date-range PDF export', kind: 'fix', items: [\n    'Replaced native multi-select (invisible options in dark mode on Chrome) with a custom dropdown with search, multi-tick, Done/outside-click commit',\n    'Fixed uppercase-leak from .filter-group label cascading into option text',\n    'Added date-range picker (30d / 90d / YTD / 12m / all / custom) that feeds Analytics trend charts',\n    'PDF export button added to Dashboard, Analytics, Risk, Playbook, Backlog, Team, Insights, Renewals',\n    'Fixed Settings modal backdrop + Esc close; wired topbar urgency chips',\n  ]},\n  { date: '2026-11-11', phase: 'Phase 3', title: 'Analytics, Playbook, de-tiered, vendor navigation', kind: 'feature', items: [\n    'Centralised Analytics view with dept donut, monthly/quarterly/annual bars, category and top-vendor breakdowns, 12-month invoice trend',\n    'Clause Playbook with per-clause rules, comparators (max/min/phrase), severity, portfolio deviation matrix',\n    'All Enterprise gating removed - one tier while in design-partner cohort',\n    'Global vendor-click navigation: 201 vendor-name elements wire to the contract review modal',\n  ]},\n  { date: '2026-11-11', phase: 'Phase 2', title: 'Phase 2: Contract risk engine + bulk OCR + Integration roadmap + Backlog', kind: 'feature', items: [\n    'Risk Analytics view with 8-dimension scoring: Financial, Legal, Operational, Functional, Usage, Data & Security, Compliance, Vendor concentration',\n    'Portfolio-wide heatmap of missing critical clauses',\n    'Bulk contract ingestion with drag-and-drop, Tesseract.js OCR lazy-loaded from CDN for scanned PDFs',\n    'Expanded clause taxonomy from 4 to 18 clauses',\n    'Industry-aware weighting (BFSI, Healthcare, SaaS, Manufacturing, Public, Retail)',\n    'Integration Roadmap with 77 target systems grouped into 13 categories',\n    'Owner-only Product Backlog with 14 pre-seeded limitations/bugs/features',\n  ]},\n  { date: '2026-11-10', phase: 'Phase 1', title: 'Enterprise UI redesign + sample company', kind: 'feature', items: [\n    'New design system: Inter font, neutral light theme with dark toggle, sidebar nav',\n    '28 realistic vendors with contract terms, licence data, owners',\n    '74 invoices across paid / pending / overdue',\n    '16-person directory; 29 HRMS connectors catalogued',\n    'Non-PII datasheet template with PII guard at import',\n  ]},\n  { date: '2026-11-10', phase: 'Phase 0', title: 'Rollback from Overcharge Finder rebuild', kind: 'fix', items: [\n    'Reverted the 12 Aug rebuild that replaced the full dashboard with a narrower Overcharge Finder',\n    'Restored every original feature: subscription dashboard, invoice tracking, renewal calendar, contract term extraction',\n    'Main branch now serves the full feature set',\n  ]},\n];\n\nconst DEFAULT_ROADMAP = [\n  // --- TIER 1: UNBLOCKS BACKEND + REAL DATA ---\n  { id: 'rm-01', theme: 'Backend foundation', status: 'next', title: 'Server tier: Node + Postgres + S3 object storage',\n    body: 'Ship the backend that the current client-only app assumes. Users and workspaces become real. All state migrates from localStorage to the API.',\n    scope: ['Multi-tenant Postgres with row-level isolation', 'Session + API key auth', 'S3-compatible contract file storage', 'Server-side worker for alerts and renewal computation'], upvotes: 12 },\n  { id: 'rm-02', theme: 'Backend foundation', status: 'next', title: 'Real email delivery for invites and alerts',\n    body: 'SMTP (Postmark or SES) for invite links, owner alerts and digest emails. Replaces the current mailto drafts.', scope: ['Transactional email template library', 'Unsubscribe + bounce handling', 'Signed acknowledgement links'], upvotes: 10 },\n  { id: 'rm-03', theme: 'Backend foundation', status: 'next', title: 'Real OAuth for the first five connectors',\n    body: 'Convert the simulated connect flow into real OAuth for Okta, Google Workspace, Microsoft Entra ID, Slack and QuickBooks. Keep the client UI identical; swap the handler.',\n    scope: ['OAuth app registration per provider', 'Token refresh and encrypted storage', 'Scheduled sync worker (every 6 hours)', 'Error recovery on expired tokens'], upvotes: 15 },\n\n  // --- TIER 2: ENTERPRISE READINESS ---\n  { id: 'rm-04', theme: 'Enterprise readiness', status: 'planned', title: 'Multi-entity / group company dimension',\n    body: 'Group companies with multiple legal entities need spend rolled up per entity. Currently single-tenant per workspace.', scope: ['Legal entity field on every subscription and invoice', 'Entity-level rollup in Analytics', 'Approval policy rules scoped per entity'], upvotes: 7 },\n  { id: 'rm-05', theme: 'Enterprise readiness', status: 'planned', title: 'Audit log view',\n    body: 'Immutable audit log of every meaningful action (approvals, decisions, data exports). Already captured in state; needs a surface + SIEM forward.',\n    scope: ['Audit log UI with filter + search', 'JSON export for SIEM', 'Signed webhooks for critical events'], upvotes: 5 },\n  { id: 'rm-06', theme: 'Enterprise readiness', status: 'planned', title: 'Tunable risk weights per customer',\n    body: 'Risk-engine weights are currently static. Customers (especially BFSI) will want to override - e.g. weight liability cap higher than vendor concentration.',\n    scope: ['Weight editor in Settings', 'Per-dimension weight slider', 'Industry defaults preserved as presets'], upvotes: 4 },\n  { id: 'rm-07', theme: 'Enterprise readiness', status: 'planned', title: 'SSO for Login (SAML 2.0 / OIDC)',\n    body: 'Customer logs in with their own Okta / Entra ID / Google Workspace; SCIM for provisioning.',\n    scope: ['SAML 2.0 service provider', 'SCIM 2.0 user and group provisioning', 'Role mapping from IdP groups'], upvotes: 8 },\n\n  // --- TIER 3: PRODUCT DEPTH ---\n  { id: 'rm-08', theme: 'Product depth', status: 'planned', title: 'Vendor contact book',\n    body: 'Capture rep name, direct email, phone, last outreach date, renewal notes per vendor. Renewals become context-rich conversations.',\n    scope: ['Contact table on each subscription', 'Last-outreach timestamp', 'Pre-filled renegotiation email templates'], upvotes: 6 },\n  { id: 'rm-09', theme: 'Product depth', status: 'planned', title: 'Price benchmarking across the cohort',\n    body: '\"What others pay\" benchmarks for each vendor. Needs opt-in anonymised data sharing across the design-partner base.',\n    scope: ['Opt-in benchmark participation', 'Anonymised quarterly medians per vendor', 'Benchmark line on contract review'], upvotes: 9 },\n  { id: 'rm-10', theme: 'Product depth', status: 'shipped', title: 'AI chat on the whole contract corpus',\n    body: 'Shipped in Phase 12 - text and voice Q&A grounded in your own data, 14 intent patterns, clickable source trail. Next: semantic search across full contract text via embeddings when the server tier ships.',\n    scope: ['Shipped: 14 intents, text + voice, grounded citations, chat history', 'Next: embeddings over ingested contract PDFs', 'Next: role-aware answers (Finance sees spend, Legal sees terms)'], upvotes: 15 },\n  { id: 'rm-18', theme: 'Product depth', status: 'planned', title: 'ElevenLabs voice (BYOK) for multilingual soothing replies',\n    body: 'Ask Track replies through ElevenLabs Multilingual v2 - 29+ languages including 9 Indian languages, far less robotic than browser Web Speech. BYOK pattern so each workspace uses their own free tier (10k chars/month). Full managed experience ships once the server tier lands and we can proxy the API without exposing keys.',\n    scope: ['Settings → Voice pane: API key input, voice picker from the user\\'s ElevenLabs library, language selector', 'Streaming audio for low-latency playback', 'Keep browser native SpeechRecognition for STT (already multilingual + free)', 'Test voice button', 'Fall back to current Web Speech when no key is set', 'Post-backend: proxy all requests through server, one managed voice service for all workspaces, GST-billed as part of the plan'], upvotes: 8 },\n  { id: 'rm-17', theme: 'Product depth', status: 'shipped', title: 'Licence forecasting (capacity planning)',\n    body: 'Shipped in Phase 13 - quarterly demand model per vendor with org/dept growth, utilisation target and confidence buffer.',\n    scope: ['Shipped: per-vendor Q+1 to Q+4 demand, cost impact, portfolio curve', 'Next: Rippling / BambooHR hooks to pull live headcount into the capacity plan', 'Next: confidence intervals, not single-point estimates'], upvotes: 10 },\n  { id: 'rm-11', theme: 'Product depth', status: 'exploring', title: 'Cancellation letter generator',\n    body: 'Pre-drafted cancellation notices per vendor jurisdiction, formatted for delivery (email, courier, in-app). Vendor-specific signing requirements captured.',\n    scope: ['Template library per vendor', 'Jurisdiction-specific legal language', 'DocuSign send integration'], upvotes: 3 },\n\n  // --- TIER 4: GROWTH / COMMERCIAL ---\n  { id: 'rm-12', theme: 'Commercial', status: 'planned', title: 'Public site + pricing calculator',\n    body: 'Expand the marketing site with a pricing calculator that outputs a rough quote per employee count or vendor count. Adds a changelog page.',\n    scope: ['Per-vendor-count tier table', 'Employee-count-based calculator', 'Public changelog page synced from the in-app changelog'], upvotes: 4 },\n  { id: 'rm-13', theme: 'Commercial', status: 'planned', title: 'Distributor one-pager PDF',\n    body: 'Export a branded one-pager for the distributor to hand to prospects. Summary + on-prem claim + one screenshot + trial link.', scope: ['Single-page PDF generated from the current product', 'Customisable with prospect name', 'QR code to a prospect-specific trial'], upvotes: 2 },\n  { id: 'rm-14', theme: 'Commercial', status: 'exploring', title: 'In-app upgrade + billing (Razorpay)',\n    body: 'When trials end, convert in-app. Razorpay subscription billing with GST invoices.',\n    scope: ['Razorpay subscription setup', 'GST-compliant invoices', 'Plan change / downgrade flow'], upvotes: 5 },\n\n  // --- TIER 5: COLLABORATION + MOBILE ---\n  { id: 'rm-15', theme: 'Collaboration', status: 'planned', title: 'Microsoft Teams + Slack 2-way',\n    body: 'Receive owner acknowledgements from Teams/Slack buttons instead of in-app. Slack already sends; Teams adaptive cards needed.',\n    scope: ['Teams adaptive card for alerts', 'Slack interactive buttons for Acknowledge/Escalate', 'Bidirectional link between the message and the in-app alert'], upvotes: 7 },\n  { id: 'rm-16', theme: 'Collaboration', status: 'exploring', title: 'Native mobile app (iOS + Android)',\n    body: 'The current mobile owner surface is a responsive view. A real app gets push notifications and biometric auth.',\n    scope: ['React Native shell reusing the web components', 'APNs + FCM push', 'Biometric unlock'], upvotes: 3 },\n];\n\n/* ---------------- State ---------------- */\nfunction changelog() { platformSettings.changelog = platformSettings.changelog || CHANGELOG; return platformSettings.changelog; }\nfunction roadmap() { platformSettings.roadmap = platformSettings.roadmap || DEFAULT_ROADMAP; return platformSettings.roadmap; }\nfunction upvotedSet() { platformSettings.upvotedRoadmap = platformSettings.upvotedRoadmap || {}; return platformSettings.upvotedRoadmap; }\n\n/* ---------------- Render ---------------- */\nfunction renderChangelogRoadmap() {\n  const host = document.getElementById('cr-body'); if (!host) return;\n  const tab = platformSettings.crTab || 'changelog';\n\n  host.innerHTML = `\n    <div class=\"cr-tabs\">\n      <button class=\"cr-tab ${tab === 'changelog' ? 'active' : ''}\" data-cr-tab=\"changelog\">Release notes <span class=\"badge\">${changelog().length}</span></button>\n      <button class=\"cr-tab ${tab === 'roadmap' ? 'active' : ''}\" data-cr-tab=\"roadmap\">Roadmap <span class=\"badge\">${roadmap().length}</span></button>\n      <div style=\"margin-left:auto;display:flex;gap:6px\">\n        ${tab === 'changelog' ? '<button class=\"icon-btn\" id=\"cl-add\">+ Add release</button>' : '<button class=\"icon-btn\" id=\"rm-add\">+ Add item</button>'}\n        <button class=\"icon-btn\" data-pdf-export=\"cr-body\" data-pdf-title=\"${tab === 'changelog' ? 'Release notes' : 'Roadmap'}\">Download PDF</button>\n      </div>\n    </div>\n    ${tab === 'changelog' ? renderChangelogBody() : renderRoadmapBody()}\n  `;\n\n  host.querySelectorAll('[data-cr-tab]').forEach(b => b.onclick = () => { platformSettings.crTab = b.dataset.crTab; persistPlatformSettings(); renderChangelogRoadmap(); });\n  if (tab === 'changelog') wireChangelog(host);\n  else wireRoadmap(host);\n}\n\nfunction renderChangelogBody() {\n  const items = changelog();\n  // Group by month\n  const groups = {};\n  items.forEach(it => { const m = it.date.slice(0, 7); (groups[m] ||= []).push(it); });\n  return `<div class=\"cl-wrap\">\n    ${Object.entries(groups).sort((a,b) => b[0].localeCompare(a[0])).map(([m, rows]) => {\n      const label = new Date(m + '-01').toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });\n      return `<section class=\"cl-month\"><h3>${label}</h3>\n        ${rows.map(r => `<article class=\"cl-entry cl-kind-${r.kind}\" data-cl-id=\"${r.date + '-' + r.phase}\">\n          <div class=\"cl-head\">\n            <div>\n              <div class=\"cl-date\">${new Date(r.date).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })} · <span class=\"cl-phase\">${escapeHtml(r.phase)}</span></div>\n              <h4>${escapeHtml(r.title)}</h4>\n            </div>\n            <span class=\"badge ${r.kind === 'fix' ? 'warn' : r.kind === 'feature' ? 'ok' : 'info'}\">${r.kind}</span>\n          </div>\n          <ul>${r.items.map(i => `<li>${escapeHtml(i)}</li>`).join('')}</ul>\n        </article>`).join('')}\n      </section>`;\n    }).join('')}\n  </div>`;\n}\n\nfunction renderRoadmapBody() {\n  const items = roadmap();\n  const themes = {};\n  items.forEach(it => { (themes[it.theme] ||= []).push(it); });\n  const upvoted = upvotedSet();\n  return `<div class=\"rm-wrap\">\n    ${Object.entries(themes).map(([theme, rows]) => `<section class=\"rm-theme\">\n      <h3>${escapeHtml(theme)} <span class=\"badge\">${rows.length}</span></h3>\n      <div class=\"rm-grid\">${rows.sort((a, b) => (b.upvotes || 0) - (a.upvotes || 0)).map(r => `\n        <div class=\"rm-card rm-status-${r.status}\" data-rm-id=\"${r.id}\">\n          <div class=\"rm-card-head\">\n            <span class=\"badge ${r.status === 'next' ? 'info' : r.status === 'planned' ? '' : 'warn'}\">${r.status === 'next' ? 'Up next' : r.status === 'planned' ? 'Planned' : 'Exploring'}</span>\n            <button class=\"rm-vote ${upvoted[r.id] ? 'voted' : ''}\" data-rm-vote=\"${r.id}\" title=\"Vote this up\"><svg viewBox=\"0 0 24 24\" width=\"12\" height=\"12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><path d=\"M18 15l-6-6-6 6\"/></svg> ${(r.upvotes || 0)}</button>\n          </div>\n          <h4>${escapeHtml(r.title)}</h4>\n          <p>${escapeHtml(r.body)}</p>\n          ${r.scope?.length ? `<details class=\"rm-scope\"><summary>Scope</summary><ul>${r.scope.map(s => `<li>${escapeHtml(s)}</li>`).join('')}</ul></details>` : ''}\n          <div class=\"rm-foot\">\n            <select class=\"rm-status-select\" data-rm-status=\"${r.id}\">\n              ${['next','planned','exploring','shipped','deferred'].map(s => `<option value=\"${s}\" ${r.status === s ? 'selected' : ''}>${s === 'next' ? 'Up next' : s[0].toUpperCase() + s.slice(1)}</option>`).join('')}\n            </select>\n            <button class=\"link\" data-rm-remove=\"${r.id}\">Remove</button>\n          </div>\n        </div>`).join('')}</div>\n    </section>`).join('')}\n  </div>`;\n}\n\nfunction wireChangelog(host) {\n  host.querySelectorAll('[data-cl-id]').forEach(el => { /* reserved for future detail view */ });\n  const addBtn = document.getElementById('cl-add');\n  if (addBtn) addBtn.onclick = () => {\n    const title = prompt('Release title:'); if (!title) return;\n    const phase = prompt('Phase or label (e.g. \"Phase 12\", \"Fix\"):', 'Patch') || 'Patch';\n    const kind = prompt('Kind: feature / fix / breaking', 'feature') || 'feature';\n    const body = prompt('Bullet points, separated by |', '');\n    const items = (body || '').split('|').map(s => s.trim()).filter(Boolean);\n    const d = new Date().toISOString().slice(0, 10);\n    platformSettings.changelog = [{ date: d, phase, title, kind, items }, ...changelog()];\n    persistPlatformSettings(); renderChangelogRoadmap();\n    toast('Release logged.', 'success');\n  };\n}\n\nfunction wireRoadmap(host) {\n  host.querySelectorAll('[data-rm-vote]').forEach(b => b.onclick = () => {\n    const id = b.dataset.rmVote;\n    const u = upvotedSet();\n    const item = roadmap().find(x => x.id === id);\n    if (!item) return;\n    if (u[id]) { item.upvotes = Math.max(0, (item.upvotes || 0) - 1); delete u[id]; }\n    else { item.upvotes = (item.upvotes || 0) + 1; u[id] = new Date().toISOString(); }\n    platformSettings.upvotedRoadmap = u;\n    persistPlatformSettings(); renderChangelogRoadmap();\n  });\n  host.querySelectorAll('[data-rm-status]').forEach(sel => sel.addEventListener('change', () => {\n    const id = sel.dataset.rmStatus; const item = roadmap().find(x => x.id === id);\n    if (!item) return; item.status = sel.value; persistPlatformSettings(); renderChangelogRoadmap();\n  }));\n  host.querySelectorAll('[data-rm-remove]').forEach(b => b.onclick = () => {\n    if (!confirm('Remove this roadmap item?')) return;\n    platformSettings.roadmap = roadmap().filter(x => x.id !== b.dataset.rmRemove);\n    persistPlatformSettings(); renderChangelogRoadmap();\n  });\n  const addBtn = document.getElementById('rm-add');\n  if (addBtn) addBtn.onclick = () => {\n    const title = prompt('Roadmap item title:'); if (!title) return;\n    const theme = prompt('Theme:', 'Product depth') || 'Product depth';\n    const body = prompt('One-line description:', '') || '';\n    const scope = (prompt('Scope bullets, separated by |', '') || '').split('|').map(s => s.trim()).filter(Boolean);\n    const status = prompt('Status: next / planned / exploring', 'planned') || 'planned';\n    platformSettings.roadmap = [{ id: 'rm-cus-' + crypto.randomUUID().slice(0, 6), theme, status, title, body, scope, upvotes: 0 }, ...roadmap()];\n    persistPlatformSettings(); renderChangelogRoadmap();\n    toast('Roadmap item added.', 'success');\n  };\n}\n\n/* ---------------- View + nav ---------------- */\nfunction ensureChangelogView() {\n  if (document.getElementById('changelog')) return;\n  const main = document.querySelector('.main-area main'); if (!main) return;\n  const section = document.createElement('section');\n  section.id = 'changelog'; section.className = 'view';\n  section.innerHTML = `\n    <div class=\"section-head\"><div><h2>Changelog &amp; roadmap</h2><p class=\"page-sub\">Everything shipped so far, and what's next. Both are maintained in-product so the whole team sees the latest.</p></div></div>\n    <div id=\"cr-body\"></div>\n  `;\n  main.appendChild(section);\n}\nfunction ensureChangelogNav() {\n  const groups = document.querySelectorAll('.sidebar .nav-group');\n  const workspaceGroup = [...groups].find(g => g.querySelector('[data-view=\"integrations\"]')) || [...groups][groups.length-1];\n  if (!workspaceGroup || workspaceGroup.querySelector('[data-view=\"changelog\"]')) return;\n  const svg = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"/><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"/><polyline points=\"10 9 9 9 8 9\"/></svg>';\n  const btn = document.createElement('button');\n  btn.className = 'tab'; btn.dataset.view = 'changelog';\n  btn.innerHTML = `${svg}<span>Changelog &amp; roadmap</span>`;\n  workspaceGroup.appendChild(btn);\n  btn.addEventListener('click', () => switchView('changelog'));\n}\nfunction patchSwitchViewForChangelog() {\n  if (window._crSwitchPatched) return;\n  const _orig = window.switchView;\n  window.switchView = function (name, opts = {}) {\n    if (name === 'changelog') {\n      document.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t.dataset.view === name));\n      document.querySelectorAll('.view').forEach(v => v.classList.toggle('active', v.id === name));\n      window.scrollTo({ top: 0 });\n      const crumb = document.getElementById('page-crumb'); if (crumb) crumb.textContent = 'Changelog & roadmap';\n      if (!opts.replaceHistory) {\n        const target = '#changelog';\n        if (location.hash !== target) history.pushState({ view: name }, '', target);\n      }\n      return;\n    }\n    return _orig(name, opts);\n  };\n  window._crSwitchPatched = true;\n}\n\n/* Hook renderAll */\nconst _prevAll12 = typeof renderAll === 'function' ? renderAll : null;\nif (_prevAll12) {\n  window.renderAll = function () {\n    _prevAll12();\n    try {\n      ensureChangelogView();\n      ensureChangelogNav();\n      patchSwitchViewForChangelog();\n      renderChangelogRoadmap();\n    } catch (e) { console.warn(e); }\n  };\n}\ndocument.addEventListener('DOMContentLoaded', () => {\n  setTimeout(() => {\n    try {\n      ensureChangelogView();\n      ensureChangelogNav();\n      patchSwitchViewForChangelog();\n      renderChangelogRoadmap();\n    } catch (_) {}\n  }, 550);\n});\n\n\n;\n\n/* ==========================================================================\n   SaaS Spend Track - Phase 22\n   Distributor one-pager\n   ---------------------------------------------------------------------------\n   Branded A4 leave-behind the distributor can print or email to each\n   prospect. Rendered inline for preview with a Download PDF button\n   that routes through the existing universal download bridge.\n\n   Design: single A4 page (210mm x 297mm), 4 bands:\n   1. Hero: logo, product name, one-line value prop, prospect name\n      (optional personalisation field)\n   2. The problem (one sentence) + three solution columns\n   3. Pricing card (one tier)\n   4. CTA band with QR code to saasspendtrack.com and company info\n\n   Personalisation: prospect name + distributor name are editable in the\n   preview and bake into the PDF. State persists so the same values come\n   back next time.\n   ========================================================================== */\n\nfunction onepagerSettings() {\n  platformSettings.onepager = platformSettings.onepager || {\n    prospectName: '',\n    distributorName: 'Vinay Raghavendran',\n    distributorEmail: 'vinay@saasspendtrack.com',\n    distributorPhone: '+91 91684 81989',\n    accentColor: '#0f2a5e',\n  };\n  return platformSettings.onepager;\n}\n\n/* ---------------- Render ---------------- */\nfunction renderOnepager() {\n  const host = document.getElementById('op-body');\n  if (!host) return;\n  const s = onepagerSettings();\n\n  host.innerHTML = `\n    <div class=\"op-controls\">\n      <div class=\"op-ctrl-row\">\n        <label>Prospect name <input id=\"op-prospect\" value=\"${escapeHtml(s.prospectName)}\" placeholder=\"e.g. Acme Corp\"/></label>\n        <label>Distributor name <input id=\"op-distributor\" value=\"${escapeHtml(s.distributorName)}\" placeholder=\"Your name\"/></label>\n        <label>Distributor email <input id=\"op-dist-email\" value=\"${escapeHtml(s.distributorEmail)}\" placeholder=\"you@firm.com\"/></label>\n        <label>Distributor phone <input id=\"op-dist-phone\" value=\"${escapeHtml(s.distributorPhone)}\" placeholder=\"+91 ...\"/></label>\n      </div>\n      <div class=\"op-ctrl-row\" style=\"margin-top:8px\">\n        <button class=\"btn-primary\" id=\"op-download\">Download PDF</button>\n        <button class=\"icon-btn\" id=\"op-print\">Print</button>\n        <span class=\"dim\" style=\"font-size:12px;margin-left:auto\">A4 single page · ready to print or email</span>\n      </div>\n    </div>\n\n    <div class=\"op-page-wrap\">\n      <div id=\"op-page\" class=\"op-page\">\n        ${onepagerHtml(s)}\n      </div>\n    </div>\n  `;\n\n  // Wire inputs\n  const sync = () => {\n    s.prospectName = document.getElementById('op-prospect').value;\n    s.distributorName = document.getElementById('op-distributor').value;\n    s.distributorEmail = document.getElementById('op-dist-email').value;\n    s.distributorPhone = document.getElementById('op-dist-phone').value;\n    persistPlatformSettings();\n    document.getElementById('op-page').innerHTML = onepagerHtml(s);\n  };\n  ['op-prospect','op-distributor','op-dist-email','op-dist-phone'].forEach(id => {\n    const el = document.getElementById(id);\n    el.oninput = sync;\n  });\n\n  document.getElementById('op-download').onclick = async () => {\n    const page = document.getElementById('op-page');\n    if (typeof window.exportElementToPdf === 'function') {\n      // Use the universal pipeline; passes through saveFileUniversal\n      const title = s.prospectName ? `saas-spend-track-for-${s.prospectName.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}` : 'saas-spend-track-onepager';\n      await _onepagerDirectPdf(page, title);\n    } else {\n      toast('PDF library not ready yet, try again in a second.', 'warn');\n    }\n  };\n  document.getElementById('op-print').onclick = () => {\n    // Open a clean print window with just the page\n    const w = window.open('', '_blank', 'width=900,height=1100');\n    // Build the print snippet via concatenation so no literal end-script\n    // tag appears in this file's own text. HTML parsers close any script\n    // block on the first end-script tag they see, regardless of context.\n    const printSnippet = '<' + 'script>setTimeout(()=>window.print(),500);</' + 'script>';\n    w.document.write(`<!doctype html><html><head><title>SaaS Spend Track - ${escapeHtml(s.prospectName || 'One-pager')}</title>\n      <style>${getOnepagerPrintCss()}</style>\n      </head><body>${document.getElementById('op-page').outerHTML}${printSnippet}</body></html>`);\n    w.document.close();\n  };\n}\n\n/* The single-page markup. Values come from state + current KPIs. */\nfunction onepagerHtml(s) {\n  const yearCount = new Date().getFullYear();\n  const accent = s.accentColor || '#0f2a5e';\n  const prospect = s.prospectName ? escapeHtml(s.prospectName) : '';\n  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?data=${encodeURIComponent('https://saasspendtrack.com' + (prospect ? '?ref=' + encodeURIComponent(s.prospectName) : ''))}&size=200x200&margin=2`;\n\n  return `\n    <!-- Band 1: Hero -->\n    <div class=\"op-hero\" style=\"background: linear-gradient(135deg, ${accent} 0%, #1a3d7a 100%);\">\n      <div class=\"op-brand\">\n        <div class=\"op-logo\">SST</div>\n        <div>\n          <div class=\"op-brand-name\">SaaS Spend Track</div>\n          <div class=\"op-brand-tag\">Every SaaS subscription and contract, in one place</div>\n        </div>\n      </div>\n      ${prospect ? `<div class=\"op-prospect\">Prepared for <b>${prospect}</b></div>` : ''}\n      <div class=\"op-hero-value\">\n        Built for Indian and APAC mid-market. Spend tracking, contract intelligence, renewals, approvals, licence forecasting, and natural-language search - in one tool, on your browser or on-prem.\n      </div>\n    </div>\n\n    <!-- Band 2: Problem + 3 pillars -->\n    <div class=\"op-section\">\n      <div class=\"op-problem\">\n        <b>The problem.</b> SaaS spend at 50-500 person companies is scattered across cards, invoices, emails and Google sheets. Vendors auto-renew before anyone notices. Legal terms are buried in PDFs. Nobody owns the full picture - finance, procurement, legal and IT each see a fragment.\n      </div>\n      <div class=\"op-pillars\">\n        <div class=\"op-pillar\">\n          <div class=\"op-pillar-icon\" style=\"background:${accent}\">1</div>\n          <div class=\"op-pillar-title\">See everything</div>\n          <div class=\"op-pillar-body\">Every contract, invoice, renewal and licence utilisation in one dashboard. Spend sliced by department, category, vendor or any time window. 44 data-source connectors for auto-pulled data.</div>\n        </div>\n        <div class=\"op-pillar\">\n          <div class=\"op-pillar-icon\" style=\"background:${accent}\">2</div>\n          <div class=\"op-pillar-title\">Catch risk early</div>\n          <div class=\"op-pillar-body\">8-dimension risk engine scores every contract on financial, legal, operational, functional, usage, data, compliance and vendor-concentration risk. Clause playbook flags any deviation from your legal team's accepted terms.</div>\n        </div>\n        <div class=\"op-pillar\">\n          <div class=\"op-pillar-icon\" style=\"background:${accent}\">3</div>\n          <div class=\"op-pillar-title\">Act before renewal</div>\n          <div class=\"op-pillar-body\">Renewal command centre groups vendors by lane. Approval chains + per-clause commenting pulls finance, legal, security and procurement into one thread. Scenario planner models cancel, downgrade and renegotiate with annual impact.</div>\n        </div>\n      </div>\n    </div>\n\n    <!-- Band 3: Pricing + differentiator -->\n    <div class=\"op-section op-pricing-band\">\n      <div class=\"op-pricing\">\n        <div class=\"op-price-head\">One plan. Everything included.</div>\n        <div class=\"op-price-main\">$3,499<span>/year</span></div>\n        <div class=\"op-price-inr\">Billed annually · Indian customers: 18% GST added at checkout · Includes 250 active contracts · $100/yr per 50 additional</div>\n        <div class=\"op-price-list\">Unlimited users · Unlimited departments · Every feature · Trial free, no credit card</div>\n      </div>\n      <div class=\"op-diff\">\n        <div class=\"op-diff-title\">Why this, not Zluri or Spendflo?</div>\n        <ul>\n          <li><b>Built for India &amp; APAC</b> - lakh/crore, Indian SaaS stack seeded, INR invoicing supported</li>\n          <li><b>On-prem available</b> for BFSI, healthcare, public sector and other regulated industries</li>\n          <li><b>10× cheaper</b> than US enterprise alternatives (Zluri starts at ~$30,000/year)</li>\n          <li><b>Browser-only</b> - data never leaves your organisation unless you choose to sync a connector</li>\n          <li><b>Live in minutes</b>, not months - no implementation team</li>\n        </ul>\n      </div>\n    </div>\n\n    <!-- Band 4: CTA + QR -->\n    <div class=\"op-cta\">\n      <div class=\"op-cta-left\">\n        <div class=\"op-cta-headline\">Try it live right now.</div>\n        <div class=\"op-cta-url\">saasspendtrack.com</div>\n        <div class=\"op-cta-sub\">Scan or type the URL. Trial opens straight in your browser with a seed dataset. No signup required to look around.</div>\n        ${(s.distributorName || s.distributorEmail || s.distributorPhone) ? `\n          <div class=\"op-cta-contact\">\n            ${s.distributorName ? `<div><b>${escapeHtml(s.distributorName)}</b></div>` : ''}\n            ${s.distributorEmail ? `<div>${escapeHtml(s.distributorEmail)}</div>` : ''}\n            ${s.distributorPhone ? `<div>${escapeHtml(s.distributorPhone)}</div>` : ''}\n          </div>\n        ` : ''}\n      </div>\n      <div class=\"op-cta-qr\">\n        <img src=\"${qrUrl}\" alt=\"QR code to saasspendtrack.com\" width=\"110\" height=\"110\"/>\n        <div class=\"op-cta-qr-label\">Scan to open</div>\n      </div>\n    </div>\n\n    <!-- Footer -->\n    <div class=\"op-footer\">\n      <span>Whizzlead Solutions OPC Private Limited · HSR Layout, Bengaluru 560102</span>\n      <span>${yearCount} · One-pager v1</span>\n    </div>\n  `;\n}\n\n/* PDF render path - uses the html2pdf lib loaded by extensions3.js,\n   routed through the universal download bridge. */\nasync function _onepagerDirectPdf(el, filename) {\n  const lib = await (window.loadHtml2Pdf ? window.loadHtml2Pdf() : window.html2pdf);\n  if (!lib) { toast('PDF library failed to load.', 'error'); return; }\n  const worker = lib().set({\n    margin: 0,\n    filename: filename + '.pdf',\n    image: { type: 'jpeg', quality: 0.95 },\n    html2canvas: { scale: 2, useCORS: true, backgroundColor: '#ffffff' },\n    jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },\n  }).from(el);\n  if (typeof window.saveFileUniversal === 'function') {\n    const blob = await worker.outputPdf('blob');\n    await window.saveFileUniversal(filename + '.pdf', blob, 'application/pdf');\n  } else {\n    await worker.save();\n    toast('One-pager downloaded.', 'success');\n  }\n}\n\n/* Print CSS for the new-window print path */\nfunction getOnepagerPrintCss() {\n  return `\n    @page { size: A4; margin: 0; }\n    body { margin: 0; font-family: -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; color: #111; }\n    ${getOnepagerCss()}\n  `;\n}\nfunction getOnepagerCss() {\n  return `\n    .op-page { width: 210mm; min-height: 297mm; box-sizing: border-box; background: #fff; display: flex; flex-direction: column; font-size: 10.5px; line-height: 1.45; color: #111; }\n    .op-hero { padding: 18mm 18mm 12mm; color: #fff; }\n    .op-brand { display: flex; align-items: center; gap: 12px; margin-bottom: 8mm; }\n    .op-logo { width: 48px; height: 48px; background: #fff; color: #0f2a5e; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 20px; border-radius: 8px; letter-spacing: -0.02em; }\n    .op-brand-name { font-size: 22px; font-weight: 700; letter-spacing: -0.02em; }\n    .op-brand-tag { font-size: 11px; opacity: 0.85; margin-top: 2px; }\n    .op-prospect { display: inline-block; background: rgba(255,255,255,0.14); padding: 4px 12px; border-radius: 20px; font-size: 11px; margin-bottom: 6mm; }\n    .op-prospect b { font-weight: 600; }\n    .op-hero-value { font-size: 13px; line-height: 1.5; max-width: 170mm; opacity: 0.95; }\n    .op-section { padding: 8mm 18mm; }\n    .op-problem { font-size: 10.5px; line-height: 1.55; color: #333; margin-bottom: 7mm; padding-bottom: 6mm; border-bottom: 1px solid #e5e7eb; }\n    .op-problem b { color: #111; }\n    .op-pillars { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 6mm; }\n    .op-pillar { }\n    .op-pillar-icon { width: 24px; height: 24px; color: #fff; font-weight: 700; font-size: 12px; display: flex; align-items: center; justify-content: center; border-radius: 50%; margin-bottom: 4mm; }\n    .op-pillar-title { font-size: 12px; font-weight: 700; margin-bottom: 2mm; color: #111; }\n    .op-pillar-body { font-size: 9.5px; line-height: 1.5; color: #444; }\n    .op-pricing-band { display: grid; grid-template-columns: 1fr 1fr; gap: 8mm; align-items: start; background: #f8fafc; }\n    .op-pricing { background: #0f2a5e; color: #fff; padding: 7mm; border-radius: 8px; }\n    .op-price-head { font-size: 11px; opacity: 0.85; margin-bottom: 2mm; }\n    .op-price-main { font-size: 32px; font-weight: 800; letter-spacing: -0.02em; line-height: 1; }\n    .op-price-main span { font-size: 14px; font-weight: 500; opacity: 0.7; margin-left: 4px; }\n    .op-price-inr { font-size: 10px; opacity: 0.8; margin: 3mm 0; }\n    .op-price-list { font-size: 9.5px; opacity: 0.9; border-top: 1px solid rgba(255,255,255,0.2); padding-top: 3mm; line-height: 1.5; }\n    .op-diff { }\n    .op-diff-title { font-size: 11px; font-weight: 700; margin-bottom: 3mm; color: #111; }\n    .op-diff ul { list-style: none; padding: 0; margin: 0; }\n    .op-diff ul li { font-size: 9.5px; padding: 2mm 0 2mm 6mm; position: relative; color: #333; line-height: 1.5; }\n    .op-diff ul li::before { content: \"✓\"; position: absolute; left: 0; color: #10b981; font-weight: 700; top: 2mm; }\n    .op-diff ul li b { color: #111; font-weight: 700; }\n    .op-cta { background: #0f2a5e; color: #fff; padding: 8mm 18mm; display: grid; grid-template-columns: 1fr auto; gap: 8mm; align-items: center; }\n    .op-cta-headline { font-size: 14px; font-weight: 700; margin-bottom: 2mm; }\n    .op-cta-url { font-size: 22px; font-weight: 800; letter-spacing: -0.01em; color: #fff; margin-bottom: 2mm; }\n    .op-cta-sub { font-size: 9.5px; opacity: 0.85; max-width: 110mm; line-height: 1.5; }\n    .op-cta-contact { margin-top: 4mm; font-size: 10px; opacity: 0.95; line-height: 1.5; padding-top: 3mm; border-top: 1px solid rgba(255,255,255,0.2); }\n    .op-cta-qr { background: #fff; padding: 4mm; border-radius: 6px; text-align: center; }\n    .op-cta-qr img { display: block; }\n    .op-cta-qr-label { font-size: 8.5px; color: #333; margin-top: 2mm; font-weight: 600; }\n    .op-footer { padding: 4mm 18mm; background: #0a1e42; color: rgba(255,255,255,0.7); font-size: 8px; display: flex; justify-content: space-between; }\n  `;\n}\n\n/* ---------------- View + nav ---------------- */\nfunction ensureOnepagerView() {\n  if (document.getElementById('onepager')) return;\n  const main = document.querySelector('.main-area main'); if (!main) return;\n  const section = document.createElement('section');\n  section.id = 'onepager'; section.className = 'view';\n  section.innerHTML = `\n    <div class=\"section-head\">\n      <div>\n        <h2>Distributor one-pager</h2>\n        <p class=\"page-sub\">Branded A4 leave-behind. Add your prospect's name and your own contact details, then download the PDF or print. Every detail stays in your browser.</p>\n      </div>\n    </div>\n    <div id=\"op-body\"></div>\n    <style>${getOnepagerCss()}\n      .op-controls { background: var(--panel); border: 1px solid var(--border); border-radius: 12px; padding: 14px; margin-bottom: 14px; }\n      .op-ctrl-row { display: flex; flex-wrap: wrap; gap: 10px; align-items: center; }\n      .op-ctrl-row label { display: flex; flex-direction: column; gap: 4px; font-size: 11.5px; color: var(--text-dim); flex: 1; min-width: 180px; }\n      .op-ctrl-row input, .op-ctrl-row select { background: var(--panel-2); color: var(--ink); border: 1px solid var(--border); border-radius: 6px; padding: 6px 8px; font-size: 13px; }\n      .op-page-wrap { display: flex; justify-content: center; overflow-x: auto; padding: 20px 0; background: #e5e7eb; border-radius: 12px; }\n      .op-page { box-shadow: 0 8px 32px rgba(0,0,0,0.15); transform-origin: top center; }\n      @media (max-width: 900px) { .op-page { transform: scale(0.65); margin: -140px 0; } }\n    </style>\n  `;\n  main.appendChild(section);\n  renderOnepager();\n}\nfunction ensureOnepagerNav() {\n  const groups = document.querySelectorAll('.sidebar .nav-group');\n  const g = [...groups].find(x => x.querySelector('[data-view=\"integrations\"]')) || groups[groups.length - 1];\n  if (!g || g.querySelector('[data-view=\"onepager\"]')) return;\n  const svg = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"16\" y1=\"18\" x2=\"8\" y2=\"18\"/><line x1=\"16\" y1=\"14\" x2=\"8\" y2=\"14\"/></svg>';\n  const btn = document.createElement('button');\n  btn.className = 'tab'; btn.dataset.view = 'onepager';\n  btn.innerHTML = `${svg}<span>One-pager</span>`;\n  g.appendChild(btn);\n  btn.addEventListener('click', () => switchView('onepager'));\n}\n\n/* Patch switchView for this view */\nconst _origSwForOp = window.switchView;\nif (_origSwForOp && !window._opSwitchPatched) {\n  window.switchView = function (name, opts) {\n    if (name === 'onepager') {\n      document.querySelectorAll('.tab').forEach(t => t.classList.toggle('active', t.dataset.view === name));\n      document.querySelectorAll('.view').forEach(v => v.classList.toggle('active', v.id === name));\n      window.scrollTo({ top: 0 });\n      const crumb = document.getElementById('page-crumb'); if (crumb) crumb.textContent = 'Distributor one-pager';\n      if (!opts?.replaceHistory) {\n        const target = '#onepager';\n        if (location.hash !== target) history.pushState({ view: name }, '', target);\n      }\n      renderOnepager();\n      return;\n    }\n    return _origSwForOp(name, opts);\n  };\n  window._opSwitchPatched = true;\n}\n\nif (window.PAGE_TITLES) { window.PAGE_TITLES.onepager = 'Distributor one-pager'; }\n\n/* Hook renderAll */\nconst _prevAll16 = typeof renderAll === 'function' ? renderAll : null;\nif (_prevAll16) {\n  window.renderAll = function () {\n    _prevAll16();\n    try { ensureOnepagerView(); ensureOnepagerNav(); } catch (e) { console.warn(e); }\n  };\n}\ndocument.addEventListener('DOMContentLoaded', () => {\n  setTimeout(() => { try { ensureOnepagerView(); ensureOnepagerNav(); } catch (_) {} }, 700);\n});\n\n\n;\n\n/* ==========================================================================\n   SaaS Spend Track - QA tests for Phases 22-25\n   Extends the existing TESTS registry from extensions10.js.\n   ========================================================================== */\n\n(function registerPhase22To25Tests() {\n  if (typeof TESTS === 'undefined' || typeof test !== 'function') {\n    console.warn('QA harness not loaded; skipping Phase 22-25 tests');\n    return;\n  }\n  // Ensure the base 88 tests are registered first - defineTests() guards\n  // against double-registration via TESTS.length, so we must populate\n  // the base before adding ours.\n  if (typeof defineTests === 'function') defineTests();\n\n  /* ---------- Phase 22: One-pager ---------- */\n  test('saas', 'onepager settings default to safe values', () => {\n    const s = onepagerSettings();\n    assert(typeof s === 'object', 'onepagerSettings should return object');\n    assert('prospectName' in s, 'should have prospectName');\n    assert('distributorName' in s, 'should have distributorName');\n    assert('accentColor' in s, 'should have accentColor');\n  });\n  test('saas', 'onepager html renders without prospect name', () => {\n    const html = onepagerHtml({ prospectName: '', distributorName: '', distributorEmail: '', distributorPhone: '', accentColor: '#0f2a5e' });\n    assert(typeof html === 'string', 'onepagerHtml should return string');\n    assert(html.includes('SaaS Spend Track'), 'should include product name');\n    assert(html.includes('$3,499'), 'should include USD price');\n    assert(html.includes('250 active contracts'), 'should include contract limit');\n    assert(html.includes('qrserver.com'), 'should include QR code');\n  });\n  test('saas', 'onepager html personalises with prospect name', () => {\n    const html = onepagerHtml({ prospectName: 'Nexlo Technologies', distributorName: 'JP', distributorEmail: 'jp@firm.com', distributorPhone: '+91', accentColor: '#0f2a5e' });\n    assert(html.includes('Nexlo Technologies'), 'should bake prospect name into one-pager');\n    assert(html.includes('JP'), 'should include distributor name');\n    assert(html.includes('jp@firm.com'), 'should include distributor email');\n    // The prospect name is double-encoded in the QR URL (ref value + outer QR data).\n    // We just check that it round-trips somewhere into the final HTML.\n    assert(/ref/i.test(html), 'should tag QR code URL with ref parameter');\n  });\n  test('saas', 'onepager CSS is valid', () => {\n    const css = getOnepagerCss();\n    assert(typeof css === 'string', 'CSS should be string');\n    assert(css.includes('.op-page'), 'should style .op-page');\n    assert(css.includes('210mm'), 'should use A4 width');\n    assert(css.includes('297mm'), 'should use A4 height');\n  });\n\n  /* ---------- Phase 23: Trial expiry ---------- */\n  test('saas', 'trial state is consistent', () => {\n    const t = trialState();\n    assert(typeof t === 'object', 'trialState should return object');\n    assert('isTrial' in t, 'should have isTrial');\n    assert('isPaid' in t, 'should have isPaid');\n    assert('expired' in t, 'should have expired');\n    assert('inGrace' in t, 'should have inGrace');\n  });\n  test('saas', 'force-expire sets expired to true', () => {\n    const origStart = workspace().trialStartedAt;\n    const origPlan = workspace().plan;\n    try {\n      workspace().plan = 'trial';\n      const d = new Date(); d.setDate(d.getDate() - 20);\n      workspace().trialStartedAt = d.toISOString();\n      workspace().trialDays = 14;\n      const t = trialState();\n      assert(t.expired, 'should be expired after backdating');\n      assert(!t.isPaid, 'should not be paid');\n    } finally {\n      workspace().plan = origPlan;\n      workspace().trialStartedAt = origStart;\n    }\n  });\n  test('saas', 'reset trial gives 14 fresh days', () => {\n    const origStart = workspace().trialStartedAt;\n    const origPlan = workspace().plan;\n    try {\n      workspace().plan = 'trial';\n      workspace().trialStartedAt = new Date().toISOString();\n      workspace().trialDays = 14;\n      const t = trialState();\n      assert(!t.expired, 'should not be expired');\n      assert(t.daysLeft >= 13, 'should have ~14 days left, got ' + t.daysLeft);\n    } finally {\n      workspace().plan = origPlan;\n      workspace().trialStartedAt = origStart;\n    }\n  });\n  test('saas', 'grace mode triggers at ≤3 days', () => {\n    const origStart = workspace().trialStartedAt;\n    const origPlan = workspace().plan;\n    try {\n      workspace().plan = 'trial';\n      const d = new Date(); d.setDate(d.getDate() - 12);\n      workspace().trialStartedAt = d.toISOString();\n      workspace().trialDays = 14;\n      const t = trialState();\n      assert(t.inGrace, 'should be in grace mode at 2 days left, got daysLeft=' + t.daysLeft);\n    } finally {\n      workspace().plan = origPlan;\n      workspace().trialStartedAt = origStart;\n    }\n  });\n  test('saas', 'paid plan clears expired state', () => {\n    const origPlan = workspace().plan;\n    try {\n      workspace().plan = 'paid';\n      const t = trialState();\n      assert(t.isPaid, 'should be paid');\n      assert(!t.isTrial, 'should not be trial');\n      assert(!t.expired, 'paid should never be expired');\n    } finally {\n      workspace().plan = origPlan;\n    }\n  });\n\n  /* ---------- Phase 24: Demo presets ---------- */\n  test('saas', 'all demo presets are well-formed', () => {\n    const keys = Object.keys(DEMO_PRESETS);\n    assert(keys.length === 3, `expected 3 presets, got ${keys.length}`);\n    keys.forEach(k => {\n      const p = DEMO_PRESETS[k];\n      assert(p.label, `preset ${k} missing label`);\n      assert(p.company, `preset ${k} missing company`);\n      assert(p.employees > 0, `preset ${k} missing employees`);\n      assert(Array.isArray(p.vendors) && p.vendors.length > 0, `preset ${k} missing vendors`);\n      assert(Array.isArray(p.departments) && p.departments.length > 0, `preset ${k} missing departments`);\n    });\n  });\n  test('saas', 'Indian SaaS startup preset has sensible scale', () => {\n    const p = DEMO_PRESETS['indian-saas'];\n    assertEq(p.currencyPrefix, '₹', 'should be INR');\n    assert(p.employees >= 50 && p.employees <= 120, 'employees in startup range');\n    assert(p.vendors.length >= 20, 'at least 20 vendors');\n  });\n  test('saas', 'BFSI preset is compliance-heavy', () => {\n    const p = DEMO_PRESETS['bfsi-midmarket'];\n    const names = p.vendors.map(v => v[0].toLowerCase()).join(' ');\n    assert(/okta|crowdstrike|splunk|onetrust|moody|thomson/.test(names), 'BFSI should include security/risk tools');\n    assert(p.employees >= 300, 'BFSI should have mid-market headcount');\n  });\n  test('saas', 'Manufacturing preset has ERP + CAD + MES', () => {\n    const p = DEMO_PRESETS['manufacturing'];\n    const names = p.vendors.map(v => v[0].toLowerCase()).join(' ');\n    assert(/sap|autocad|solidworks|teamcenter|rockwell/.test(names), 'manufacturing should include ERP/CAD/MES');\n  });\n  test('saas', 'buildStateFromPreset returns valid state shape', () => {\n    const built = buildStateFromPreset('indian-saas');\n    assert(built, 'should build state');\n    assert(Array.isArray(built.subscriptions), 'should have subscriptions array');\n    assert(built.subscriptions.length === DEMO_PRESETS['indian-saas'].vendors.length, 'subscription count matches preset');\n    built.subscriptions.forEach(s => {\n      assert(s.id, 'subscription needs id');\n      assert(s.name, 'subscription needs name');\n      assert(typeof s.cost === 'number', 'subscription needs numeric cost');\n      assert(s.renewal, 'subscription needs renewal date');\n    });\n  });\n  test('saas', 'preset vendors have realistic utilisation ratios', () => {\n    const built = buildStateFromPreset('bfsi-midmarket');\n    const withSeats = built.subscriptions.filter(s => s.licenses && s.activeUsers);\n    const ratios = withSeats.map(s => s.activeUsers / s.licenses);\n    const avg = ratios.reduce((a, r) => a + r, 0) / ratios.length;\n    assert(avg > 0.5 && avg <= 1.0, `BFSI avg utilisation should be realistic, got ${avg.toFixed(2)}`);\n  });\n\n  /* ---------- Phase 25: Vendor contact book ---------- */\n  test('saas', 'vendorContact returns an object', () => {\n    const sub = (state.subscriptions || [])[0];\n    if (!sub) { return; } // no data to test with\n    const c = vendorContact(sub);\n    assert(typeof c === 'object', 'should return object');\n  });\n  test('saas', 'vendorContact persists on the sub record', () => {\n    const sub = (state.subscriptions || [])[0];\n    if (!sub) return;\n    const origBook = sub.contactBook;\n    try {\n      delete sub.contactBook;\n      vendorContact(sub).email = 'test@example.com';\n      assert(sub.contactBook.email === 'test@example.com', 'should persist to sub.contactBook');\n    } finally {\n      sub.contactBook = origBook;\n    }\n  });\n  test('saas', 'draftRenewalEmail requires an email', () => {\n    const sub = (state.subscriptions || [])[0];\n    if (!sub) return;\n    const origBook = sub.contactBook;\n    try {\n      sub.contactBook = {};\n      // Should toast warn, not throw\n      let warned = false;\n      const origToast = window.toast;\n      window.toast = (msg, kind) => { if (kind === 'warn') warned = true; };\n      try { draftRenewalEmail(sub.id); } catch (_) {}\n      window.toast = origToast;\n      assert(warned, 'should warn when contact has no email');\n    } finally {\n      sub.contactBook = origBook;\n    }\n  });\n\n  /* ---------- Cross-cutting: everything renders without error ---------- */\n  test('integration', 'all new views exist after load', () => {\n    const viewIds = ['onepager', 'demo-presets', 'contacts', 'changelog', 'chat', 'forecast'];\n    viewIds.forEach(id => {\n      assert(document.getElementById(id), `view #${id} should exist`);\n    });\n  });\n  test('integration', 'all new nav buttons wire to switchView', () => {\n    const navIds = ['onepager', 'demo-presets', 'contacts', 'changelog', 'chat', 'forecast'];\n    navIds.forEach(id => {\n      const btn = document.querySelector(`[data-view=\"${id}\"]`);\n      assert(btn, `nav button for ${id} should exist`);\n    });\n  });\n  test('integration', 'switchView routes to new views', () => {\n    const before = document.querySelector('.view.active')?.id;\n    try {\n      ['onepager', 'demo-presets', 'contacts'].forEach(name => {\n        switchView(name, { replaceHistory: true });\n        const active = document.querySelector('.view.active');\n        assertEq(active?.id, name, `switchView(${name}) should activate view`);\n      });\n    } finally {\n      if (before) switchView(before, { replaceHistory: true });\n    }\n  });\n\n  /* ---------- Download bridge ---------- */\n  test('integration', 'saveFileUniversal is defined', () => {\n    assert(typeof saveFileUniversal === 'function', 'bridge should be loaded');\n  });\n  test('integration', 'downloadFile is patched to bridge', () => {\n    assert(window._origDownloadFile, 'original downloadFile should be preserved');\n    assert(window.downloadFile !== window._origDownloadFile, 'downloadFile should be wrapped');\n  });\n\n  /* ---------- Voice settings ---------- */\n  test('saas', 'voice settings defaults to English TTS', () => {\n    const vs = voiceSettings();\n    assertEq(vs.ttsLang.split('-')[0], 'en', 'TTS should default to English');\n  });\n  test('saas', 'voice settings supports 12 languages', () => {\n    assert(VOICE_LANGS.length === 12, `expected 12 languages, got ${VOICE_LANGS.length}`);\n    const codes = VOICE_LANGS.map(l => l.code);\n    ['en-US','en-IN','en-GB','hi-IN','ta-IN','te-IN','bn-IN','mr-IN','gu-IN','kn-IN','ml-IN','pa-IN'].forEach(c => {\n      assert(codes.includes(c), `should support ${c}`);\n    });\n  });\n  test('saas', 'speakOn defaults to true', () => {\n    assert(voiceSettings().speakOn === true, 'speak should default on');\n  });\n\n  /* ---------- Ask Track intent routing ---------- */\n  test('saas', 'Ask Track routes \"spend on <vendor>\" to spend_on_vendor', () => {\n    const p = routeChatQuery('spend on Salesforce');\n    assertEq(p.intent, 'spend_on_vendor', `expected spend_on_vendor, got ${p.intent}`);\n  });\n  test('saas', 'Ask Track routes \"total spend on X this year\" to spend_on_vendor (not dept_vendor)', () => {\n    const p = routeChatQuery('what is the total spend on hubspot this year');\n    assertEq(p.intent, 'spend_on_vendor', `should not misroute to dept_vendor, got ${p.intent}`);\n  });\n  test('saas', 'Ask Track routes dept+vendor only with explicit dept keyword', () => {\n    const p = routeChatQuery('how much is the marketing team spending on hubspot');\n    assertEq(p.intent, 'spend_by_dept_vendor', `should route dept+vendor with team keyword, got ${p.intent}`);\n  });\n  test('saas', 'Ask Track routes \"list all vendors\"', () => {\n    const p = routeChatQuery('list all vendors');\n    assertEq(p.intent, 'list_vendors', `expected list_vendors, got ${p.intent}`);\n  });\n  test('saas', 'Ask Track routes \"give me all vendor names\" (the bug from the screenshot)', () => {\n    const p = routeChatQuery('give me all vendor names');\n    assertEq(p.intent, 'list_vendors', `expected list_vendors, got ${p.intent}`);\n  });\n  test('saas', 'Ask Track routes help', () => {\n    const p = routeChatQuery('help');\n    assertEq(p.intent, 'help', `expected help, got ${p.intent}`);\n  });\n\n  /* ---------- Fuzzy vendor match (the hotspot→HubSpot bug) ---------- */\n  test('saas', 'fuzzy vendor match finds HubSpot from \"hotspot\"', () => {\n    // Needs HubSpot in state\n    const hasHub = (state.subscriptions || []).some(v => /hubspot/i.test(v.name));\n    if (!hasHub) return; // soft skip\n    const match = findVendor('hotspot');\n    assert(match, 'should find a fuzzy match for \"hotspot\"');\n    assert(/hubspot/i.test(match.name), `expected HubSpot, got ${match.name}`);\n  });\n  test('saas', 'fuzzy vendor match strips trailing timeframe', () => {\n    const hasHub = (state.subscriptions || []).some(v => /hubspot/i.test(v.name));\n    if (!hasHub) return;\n    const match = findVendor('hubspot this year');\n    assert(match, 'should find HubSpot even with trailing timeframe');\n  });\n  test('saas', 'Levenshtein distance basics', () => {\n    assertEq(_lev('abc','abc'), 0, 'identical strings');\n    assertEq(_lev('abc','abd'), 1, 'one substitution');\n    assertEq(_lev('abc','abcd'), 1, 'one insertion');\n    assertEq(_lev('hotspot','hubspot'), 2, 'hotspot to hubspot');\n  });\n\n  /* ---------- Licence Forecast ---------- */\n  test('saas', 'forecast respects headcount growth', () => {\n    const s = fcSettings();\n    const orig = { h: s.headcountGrowth, hz: s.horizon };\n    try {\n      s.headcountGrowth = 20; s.horizon = 4;\n      const rows = forecastAll();\n      if (!rows.length) return;\n      const row = rows[0];\n      assert(row.terminal >= row.active, 'with 20% growth, demand should grow');\n    } finally {\n      s.headcountGrowth = orig.h;\n      s.horizon = orig.hz;\n    }\n  });\n\n})();\n\n\n;\n\n/* ================================================================\n   Phase 51 - Expanded test coverage for Phases 43-50\n   ================================================================\n   API-boundary tests: verify handles exist, modules loaded, patches\n   applied. No state mutations, no modal opens, no renderAll calls\n   - those caused the Puppeteer test runner to hang mid-evaluation.\n\n   Deeper behavioural testing lives in trial-tracking/UAT-PHASE-43-50.md\n   for the human to walk through.\n\n   Hook pattern: wrap defineTests() from extensions10 so our tests\n   are appended after the originals.\n   ================================================================ */\n\n(() => {\n\nconst _origDefineTests = typeof window.defineTests === 'function' ? window.defineTests : null;\nif (!_origDefineTests) {\n  console.warn('[Phase 51] defineTests not found; test coverage expansion skipped');\n  return;\n}\n\nwindow.defineTests = function () {\n  _origDefineTests.apply(this, arguments);\n  // Idempotency guard - match the Phase 10 pattern (TESTS.length short-circuit).\n  // Without this, our tests get re-registered every time defineTests is called\n  // (which the test-report UI re-does on button clicks).\n  if (window._p51_tests_registered) return;\n  window._p51_tests_registered = true;\n\n  // ---------- Phase 43: onboarding ----------\n\n  test('phase43.onboarding', 'window.OnboardHelp public handle exists', () => {\n    assert(typeof window.OnboardHelp === 'object', 'OnboardHelp missing');\n    ['open', 'runFlow', 'resetChecklist', 'resetAll'].forEach(k =>\n      assert(typeof window.OnboardHelp[k] === 'function', `OnboardHelp.${k} missing`));\n  });\n\n  // ---------- Phase 44: bulk CSV import ----------\n\n  test('phase44.bulk', 'window.BulkImport public handle exists', () => {\n    assert(typeof window.BulkImport === 'object', 'BulkImport missing');\n    ['open', 'close', 'parseCSV', 'autoMap'].forEach(k =>\n      assert(typeof window.BulkImport[k] === 'function', `BulkImport.${k} missing`));\n  });\n\n  test('phase44.bulk', 'parseCSV handles quoted commas', () => {\n    const rows = BulkImport.parseCSV('\"Acme, Inc.\",100\\nFoo,200');\n    assertEq(rows.length, 2, 'wrong row count');\n    assertEq(rows[0][0], 'Acme, Inc.', 'quoted comma not preserved');\n    assertEq(rows[0][1], '100', 'quoted-field col 2 lost');\n  });\n\n  test('phase44.bulk', 'parseCSV auto-detects tab delimiter', () => {\n    const rows = BulkImport.parseCSV('A\\tB\\tC\\n1\\t2\\t3');\n    assertEq(rows.length, 2, 'row count');\n    assertEq(rows[0].length, 3, 'col count');\n  });\n\n  test('phase44.bulk', 'autoMap recognises common aliases', () => {\n    const map = BulkImport.autoMap(['Vendor', 'Annual cost', 'Cycle', 'Owner', 'Renewal date']);\n    assertEq(map.name, 0, 'Vendor → name');\n    assertEq(map.cost, 1, 'Annual cost → cost');\n    assertEq(map.cycle, 2, 'Cycle → cycle');\n    assertEq(map.owner, 3, 'Owner → owner');\n    assertEq(map.renewal, 4, 'Renewal date → renewal');\n  });\n\n  test('phase44.bulk', 'autoMap recognises exotic aliases', () => {\n    const map = BulkImport.autoMap(['Tool', 'ACV', 'Frequency', 'POC']);\n    assertEq(map.name, 0, 'Tool → name');\n    assertEq(map.cost, 1, 'ACV → cost');\n    assertEq(map.cycle, 2, 'Frequency → cycle');\n    assertEq(map.owner, 3, 'POC → owner');\n  });\n\n  test('phase44.bulk', 'autoMap returns empty mapping for unrecognised headers', () => {\n    const map = BulkImport.autoMap(['foo', 'bar', 'baz']);\n    assertEq(Object.keys(map).length, 0, 'should be empty');\n  });\n\n  // ---------- Phase 46: reports ----------\n\n  test('phase46.reports', 'window.Reports public handle exists', () => {\n    assert(typeof window.Reports === 'object', 'Reports missing');\n    ['spendSummary', 'renewalRoster', 'savings', 'view'].forEach(k =>\n      assert(typeof window.Reports[k] === 'function', `Reports.${k} missing`));\n  });\n\n  test('phase46.reports', 'Reports sidebar tab present', () => {\n    const tab = document.querySelector('.tab[data-view=\"reports\"]');\n    assert(tab, 'Reports tab missing from sidebar');\n  });\n\n  test('phase46.reports', 'Reports view container exists', () => {\n    const v = document.querySelector('.view[data-view=\"reports\"]');\n    assert(v, 'reports view container missing');\n  });\n\n  // ---------- Phase 47: settings + multi-currency ----------\n\n  test('phase47.settings', 'window.Settings public handle exists', () => {\n    assert(typeof window.Settings === 'object', 'Settings missing');\n    ['open', 'setCurrency', 'refreshFx'].forEach(k =>\n      assert(typeof window.Settings[k] === 'function', `Settings.${k} missing`));\n  });\n\n  test('phase47.settings', 'Settings sidebar tab present', () => {\n    const tab = document.querySelector('.tab[data-view=\"settings\"]');\n    assert(tab, 'Settings tab missing');\n  });\n\n  test('phase47.settings', 'formatMoney is monkey-patched', () => {\n    assert(window.formatMoney._p47, 'formatMoney not patched by Phase 47');\n    assert(window.formatMoneyShort._p47, 'formatMoneyShort not patched by Phase 47');\n  });\n\n  test('phase47.settings', 'formatMoney USD returns dollar prefix', () => {\n    // Don't mutate state. Just check the USD passthrough - if no fx or\n    // currency setting is set, the patch should fall back to the original.\n    const r = formatMoney(100);\n    assert(typeof r === 'string' && r.length > 0, 'formatMoney returned invalid');\n  });\n\n  // ---------- Phase 48: payment detection ----------\n\n  test('phase48.payment', 'window.MarkPaid public handle exists', () => {\n    assert(typeof window.MarkPaid === 'object', 'MarkPaid missing');\n    ['manual', 'isPaid', 'state', 'undo'].forEach(k =>\n      assert(typeof window.MarkPaid[k] === 'function', `MarkPaid.${k} missing`));\n  });\n\n  test('phase48.payment', 'state() has required keys', () => {\n    const s = MarkPaid.state();\n    assert(s, 'state object missing');\n    ['isPaid', 'paidAt', 'paymentId', 'method', 'acknowledged'].forEach(k =>\n      assert(k in s, `paidState.${k} missing`));\n  });\n\n  // ---------- Phase 49: command palette ----------\n\n  test('phase49.cmdpal', 'window.CmdPal public handle exists', () => {\n    assert(typeof window.CmdPal === 'object', 'CmdPal missing');\n    ['open', 'close'].forEach(k =>\n      assert(typeof window.CmdPal[k] === 'function', `CmdPal.${k} missing`));\n  });\n\n  // ---------- Phase 50: per-subscription currency ----------\n\n  test('phase50.subccy', 'window.SubCurrency public handle exists', () => {\n    assert(typeof window.SubCurrency === 'object', 'SubCurrency missing');\n    ['edit', 'get', 'set'].forEach(k =>\n      assert(typeof window.SubCurrency[k] === 'function', `SubCurrency.${k} missing`));\n  });\n\n  test('phase50.subccy', 'monthlyCost is monkey-patched for USD normalization', () => {\n    assert(window.monthlyCost._p50, 'monthlyCost not patched by Phase 50');\n  });\n\n  test('phase50.subccy', 'subs without currency field default to USD passthrough', () => {\n    const sub = { cost: 500, cycle: 'yearly' };  // no currency\n    const mc = monthlyCost(sub);\n    // Should be 500/12 since cycle=yearly, no currency → USD → USD (passthrough)\n    assert(Math.abs(mc - 500 / 12) < 0.01, `expected ~${500/12}, got ${mc}`);\n  });\n\n  // ---------- Phase 52: diagnostics ----------\n\n  test('phase52.diag', 'window.Diag public handle exists', () => {\n    assert(typeof window.Diag === 'object', 'Diag missing');\n    ['check', 'runTests', 'errors', 'clear', 'reset', 'open'].forEach(k =>\n      assert(typeof window.Diag[k] === 'function', `Diag.${k} missing`));\n  });\n\n  test('phase52.diag', 'Diag.check returns a complete report', () => {\n    const r = Diag.check();\n    assert(r && typeof r === 'object', 'check returned null');\n    assert(Array.isArray(r.modules), 'modules missing');\n    assert(Array.isArray(r.patches), 'patches missing');\n    assert(Array.isArray(r.errors), 'errors missing');\n    assert(r.summary, 'summary missing');\n    // Should report all 7 modules\n    assert(r.modules.length === 7, `expected 7 modules, got ${r.modules.length}`);\n  });\n\n  test('phase52.diag', 'all 7 modules report healthy', () => {\n    const r = Diag.check();\n    const broken = r.modules.filter(m => m.status !== 'ok');\n    assert(broken.length === 0, 'broken modules: ' + broken.map(m => m.id).join(', '));\n  });\n\n  // ---------- Integration ----------\n\n  test('integration.phase43to50', 'all monkey-patches stacked without breakage', () => {\n    // formatMoney callable\n    const r = formatMoney(1000);\n    assert(typeof r === 'string', 'formatMoney broken: ' + r);\n    assert(r.length > 0, 'formatMoney returned empty');\n    // monthlyCost callable\n    const sub = { cost: 100, cycle: 'monthly', currency: 'USD' };\n    const mc = monthlyCost(sub);\n    assert(typeof mc === 'number' && !isNaN(mc), 'monthlyCost broken');\n    // switchView callable\n    assert(typeof window.switchView === 'function', 'switchView missing');\n  });\n\n  test('integration.phase43to50', 'renderAll is still a function after all patches', () => {\n    assert(typeof window.renderAll === 'function', 'renderAll missing');\n  });\n\n};\n\n})();\n\n";
